/* ===== js/utils.js ===== */
function parseLocalISOString(dateStr, timeStr) {
    if (!dateStr) return null;
    const [y, m, d] = dateStr.split('-').map(Number);
    const [h, min] = (timeStr || '00:00').split(':').map(Number);
    return new Date(y, m - 1, d, h, min, 0);
}

function parseLocalDate(dateStr) {
    if (!dateStr) return new Date();
    const parts = dateStr.split('-');
    return new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10));
}

function formatLocalDate(dateObj) {
    const y = dateObj.getFullYear();
    const m = String(dateObj.getMonth() + 1).padStart(2, '0');
    const d = String(dateObj.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
}

/** Returns today's date as 'YYYY-MM-DD' in local time. */
function getTodayStr() {
    return formatLocalDate(new Date());
}

function formatTime12h(time24) {
    if (!time24) return '';
    const [hourStr, min] = time24.split(':');
    let hour = parseInt(hourStr, 10);
    const ampm = hour >= 12 ? 'PM' : 'AM';
    hour = hour % 12;
    if (hour === 0) hour = 12;
    return `${hour}:${min} ${ampm}`;
}

function formatTaskTimeDisplay(time24) {
    if (!time24) return '';
    const is24h = (localStorage.getItem('timeFormat') || '12h') === '24h';
    if (is24h) return time24;
    return formatTime12h(time24);
}

function getStableNumericId(strId) {
    if (!strId) return Math.floor(Math.random() * 1000000) + 1;
    let hash = 0;
    for (let i = 0; i < strId.length; i++) {
        hash = strId.charCodeAt(i) + ((hash << 5) - hash);
    }
    return Math.abs(hash) % 999999 + 1; // Unique positive integer between 1 and 1,000,000
}

const audioFiles = {
    check: new Audio('sounds/check.mp3'),
    success: new Audio('sounds/success.mp3'),
    delete: new Audio('sounds/delete.mp3'),
    pomodoro: new Audio('sounds/pomodoro.mp3'),
    error: new Audio('sounds/delete.mp3') 
};

function playSound(type) {
    if (audioFiles[type]) {
        const soundClone = audioFiles[type].cloneNode();
        soundClone.volume = 0.7; 
        soundClone.play().catch(e => console.log("Audio play blocked:", e));
    }
}

function showToast(message, type = 'success', playAudio = true) {
    const container = document.getElementById('toast-container');
    if (!container) return;
    const toast = document.createElement('div');
    toast.className = `toast ${type}`;
    const icon = type === 'success' ? 'fa-check' : type === 'error' ? 'fa-xmark' : 'fa-info';
    toast.innerHTML = `<i class="fa-solid ${icon}"></i> ${message}`;
    container.appendChild(toast);
    
    if (playAudio) {
        if (type === 'success') playSound('success');
        else if (type === 'error') playSound('error');
    }

    setTimeout(() => {
        toast.classList.add('fade-out');
        setTimeout(() => toast.remove(), 300);
    }, 3000);
}

function showConfirm(message, onConfirm) {
    const modal = document.getElementById('confirm-modal');
    const msgEl = document.getElementById('confirm-message');
    const yesBtn = document.getElementById('confirm-yes');
    const noBtn = document.getElementById('confirm-no');
    if (!modal || !msgEl || !yesBtn || !noBtn) return;
    
    msgEl.textContent = message;
    modal.classList.add('active');
    playSound('error'); 

    const handleYes = () => { cleanup(); onConfirm(); };
    const handleNo = () => { cleanup(); };
    
    const cleanup = () => {
        modal.classList.remove('active');
        yesBtn.removeEventListener('click', handleYes);
        noBtn.removeEventListener('click', handleNo);
    };

    yesBtn.addEventListener('click', handleYes);
    noBtn.addEventListener('click', handleNo);
}

function getColor(priority) {
    if (priority === 'high') return '#FF4D4F';
    if (priority === 'low') return '#2F7BF6';
    return '#FFA940'; // medium or default
}

let systemThemeMedia = null;

function handleSystemThemeChange(e) {
    if (localStorage.getItem('theme') === 'system') {
        if (e.matches) {
            document.body.classList.add('dark-theme');
        } else {
            document.body.classList.remove('dark-theme');
        }
    }
}

function applyThemePreference(theme) {
    if (!systemThemeMedia) {
        systemThemeMedia = window.matchMedia('(prefers-color-scheme: dark)');
        if (systemThemeMedia.addEventListener) {
            systemThemeMedia.addEventListener('change', handleSystemThemeChange);
        } else if (systemThemeMedia.addListener) {
            systemThemeMedia.addListener(handleSystemThemeChange);
        }
    }

    if (theme === 'dark') {
        document.body.classList.add('dark-theme');
    } else if (theme === 'light') {
        document.body.classList.remove('dark-theme');
    } else {
        // system theme
        if (window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches) {
            document.body.classList.add('dark-theme');
        } else {
            document.body.classList.remove('dark-theme');
        }
    }
}

function getCategoryMeta(categoryName) {
    const defaultMeta = {
        name: 'Work',
        color: '#2F7BF6',
        bg: 'rgba(47, 123, 246, 0.12)',
        icon: 'fa-briefcase'
    };
    if (!categoryName) return defaultMeta;

    const dict = {
        'work': { name: 'Work', color: '#2F7BF6', bg: 'rgba(47, 123, 246, 0.12)', icon: 'fa-briefcase' },
        'personal': { name: 'Personal', color: '#52C41A', bg: 'rgba(82, 196, 26, 0.12)', icon: 'fa-user' },
        'study': { name: 'Study', color: '#722ED1', bg: 'rgba(114, 46, 209, 0.12)', icon: 'fa-graduation-cap' },
        'health': { name: 'Health', color: '#FA8C16', bg: 'rgba(250, 140, 22, 0.12)', icon: 'fa-heart-pulse' },
        'finance': { name: 'Finance', color: '#13C2C2', bg: 'rgba(19, 194, 194, 0.12)', icon: 'fa-wallet' },
        'other': { name: 'Other', color: '#8C8C8C', bg: 'rgba(140, 140, 140, 0.12)', icon: 'fa-tag' }
    };

    const key = String(categoryName).trim().toLowerCase();
    return dict[key] || {
        name: categoryName,
        color: '#8C8C8C',
        bg: 'rgba(140, 140, 140, 0.12)',
        icon: 'fa-tag'
    };
}
window.getCategoryMeta = getCategoryMeta;

function initCustomSelect(wrapperId, onChangeCallback) {
    const wrapper = document.getElementById(wrapperId);
    if (!wrapper) return null;

    const display = wrapper.querySelector('.custom-select-display');
    const optionsDiv = wrapper.querySelector('.custom-select-options');
    const hiddenInput = wrapper.querySelector('input[type="hidden"]');

    if (!display || !optionsDiv || !hiddenInput) return null;

    display.addEventListener('click', (e) => {
        e.stopPropagation();
        
        document.querySelectorAll('.custom-select-options.show').forEach(el => {
            if (el !== optionsDiv) el.classList.remove('show');
        });
        document.querySelectorAll('.custom-select-wrapper.open').forEach(el => {
            if (el !== wrapper) el.classList.remove('open');
        });

        optionsDiv.classList.toggle('show');
        wrapper.classList.toggle('open');
    });

    optionsDiv.addEventListener('click', (e) => {
        const option = e.target.closest('.custom-select-option');
        if (!option) return;
        
        e.stopPropagation();
        const value = option.getAttribute('data-value');
        hiddenInput.value = value;

        display.innerHTML = `${option.innerHTML} <i class="fa-solid fa-chevron-down caret-icon"></i>`;

        optionsDiv.classList.remove('show');
        wrapper.classList.remove('open');

        if (onChangeCallback) {
            onChangeCallback(value);
        }
        hiddenInput.dispatchEvent(new Event('change', { bubbles: true }));
    });

    return {
        setValue(value, customText = null) {
            hiddenInput.value = value;
            if (customText) {
                display.innerHTML = `${customText} <i class="fa-solid fa-chevron-down caret-icon"></i>`;
                return;
            }
            const opt = optionsDiv.querySelector(`.custom-select-option[data-value="${value}"]`);
            if (opt) {
                display.innerHTML = `${opt.innerHTML} <i class="fa-solid fa-chevron-down caret-icon"></i>`;
            } else {
                display.innerHTML = `${value || 'No specific task'} <i class="fa-solid fa-chevron-down caret-icon"></i>`;
            }
        },
        getValue() {
            return hiddenInput.value;
        }
    };
}
window.initCustomSelect = initCustomSelect;




