// Notes Persistence Helpers
// ==========================================
async function getNotesFromFirebase() {
    const currentUser = JSON.parse(localStorage.getItem('currentUser'));
    if (!currentUser) {
        const guestNotes = localStorage.getItem('guest_notes');
        return guestNotes ? JSON.parse(guestNotes) : [];
    }

    const localData = localStorage.getItem('firebase_notes_cache');
    const cachedNotes = localData ? JSON.parse(localData) : [];

    if (db && navigator.onLine) {
        fetchAndCacheNotesFromFirebase(currentUser.id, cachedNotes);
    }

    return cachedNotes;
}

let isFetchingBackgroundNotes = false;
async function fetchAndCacheNotesFromFirebase(currentUserId, cachedNotes) {
    if (isFetchingBackgroundNotes || !db || !navigator.onLine) return;
    isFetchingBackgroundNotes = true;

    try {
        const q = query(collection(db, "notes"), where("userId", "==", currentUserId));
        const querySnapshot = await getDocs(q);
        const notes = [];
        querySnapshot.forEach((docSnap) => {
            const data = docSnap.data();
            data.id = docSnap.id;
            notes.push(data);
        });

        localStorage.setItem('firebase_notes_cache', JSON.stringify(notes));
        window.dispatchEvent(new CustomEvent('flowtick-notes-changed'));
    } catch (err) {
        console.warn("[db] Failed to fetch notes from Firestore:", err);
    } finally {
        isFetchingBackgroundNotes = false;
    }
}

async function saveNoteToFirebase(note) {
    const currentUser = JSON.parse(localStorage.getItem('currentUser'));
    const isGuest = !currentUser;

    if (!note.id) {
        note.id = isGuest ? 'guest_note_' + Date.now() : 'note_' + Date.now();
    }
    if (!note.createdAt) note.createdAt = Date.now();
    note.updatedAt = Date.now();
    note.userId = currentUser ? currentUser.id : 'guest';

    if (isGuest) {
        let guestNotes = JSON.parse(localStorage.getItem('guest_notes')) || [];
        const idx = guestNotes.findIndex(n => String(n.id) === String(note.id));
        if (idx > -1) {
            guestNotes[idx] = note;
        } else {
            guestNotes.unshift(note);
        }
        localStorage.setItem('guest_notes', JSON.stringify(guestNotes));
        window.dispatchEvent(new CustomEvent('flowtick-notes-changed'));
        return note;
    }

    // Logged in user: optimistic local cache update
    let cachedNotes = JSON.parse(localStorage.getItem('firebase_notes_cache')) || [];
    const idx = cachedNotes.findIndex(n => String(n.id) === String(note.id));
    if (idx > -1) {
        cachedNotes[idx] = note;
    } else {
        cachedNotes.unshift(note);
    }
    localStorage.setItem('firebase_notes_cache', JSON.stringify(cachedNotes));
    window.dispatchEvent(new CustomEvent('flowtick-notes-changed'));

    if (db && navigator.onLine) {
        try {
            const dataToSave = { ...note };
            const noteId = dataToSave.id;
            delete dataToSave.id;
            if (noteId && !noteId.startsWith('note_')) {
                await updateDoc(doc(db, "notes", noteId), dataToSave);
            } else {
                const docRef = await addDoc(collection(db, "notes"), dataToSave);
                note.id = docRef.id;
                const currentCache = JSON.parse(localStorage.getItem('firebase_notes_cache')) || [];
                const cIdx = currentCache.findIndex(n => String(n.id) === String(noteId));
                if (cIdx > -1) {
                    currentCache[cIdx].id = docRef.id;
                    localStorage.setItem('firebase_notes_cache', JSON.stringify(currentCache));
                }
            }
        } catch (e) {
            console.error("[db] Error saving note to Firestore:", e);
        }
    }
    return note;
}

async function deleteNoteFromFirebase(id) {
    const currentUser = JSON.parse(localStorage.getItem('currentUser'));
    const isGuest = !currentUser;

    if (isGuest) {
        let guestNotes = JSON.parse(localStorage.getItem('guest_notes')) || [];
        guestNotes = guestNotes.filter(n => String(n.id) !== String(id));
        localStorage.setItem('guest_notes', JSON.stringify(guestNotes));
        window.dispatchEvent(new CustomEvent('flowtick-notes-changed'));
        return;
    }

    let cachedNotes = JSON.parse(localStorage.getItem('firebase_notes_cache')) || [];
    cachedNotes = cachedNotes.filter(n => String(n.id) !== String(id));
    localStorage.setItem('firebase_notes_cache', JSON.stringify(cachedNotes));
    window.dispatchEvent(new CustomEvent('flowtick-notes-changed'));

    if (db && navigator.onLine && id && !id.startsWith('note_')) {
        try {
            await deleteDoc(doc(db, "notes", id));
        } catch (e) {
            console.error("[db] Error deleting note from Firestore:", e);
        }
    }
}



/* ===== js/notifications.js ===== */
// Register native notification channels and action types on Android 8+ (API 26+)
async function registerNotificationChannels() {
    if (window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.LocalNotifications) {
        const _ln = window.Capacitor.Plugins.LocalNotifications;
        try {
            await _ln.createChannel({
                id: 'flowtick-success-channel-v6',
                name: 'FlowTick Alerts',
                description: 'Task, event and habit reminders',
                importance: 5,
                sound: 'success', // Android resource raw/success without extension
                visibility: 1,
                vibration: true,
                lights: true
            });

            await _ln.createChannel({
                id: 'flowtick-pomodoro-channel-v6',
                name: 'FlowTick Pomodoro',
                description: 'Pomodoro focus and break alarm',
                importance: 5,
                sound: 'pomodoro', // Android resource raw/pomodoro without extension
                visibility: 1,
                vibration: true,
                lights: true
            });

            await _ln.createChannel({
                id: 'flowtick-timer-live-v6',
                name: 'FlowTick Live Timer',
                description: 'Silent persistent countdown timer',
                importance: 2,   // LOW — silent, stays in drawer
                visibility: 1,
                vibration: false,
                lights: false
            });

            // Register native interactive notification action groups
            await _ln.registerActionTypes({
                types: [
                    {
                        id: 'TASK_ACTIONS',
                        actions: [
                            {
                                id: 'mark_done',
                                title: 'Mark Done'
                            },
                            {
                                id: 'wont_do',
                                title: "Won't Do"
                            }
                        ]
                    },
                    {
                        id: 'TIMER_RUNNING_ACTIONS',
                        actions: [
                            {
                                id: 'timer_pause',
                                title: 'Pause'
                            },
                            {
                                id: 'timer_stop',
                                title: 'End'
                            }
                        ]
                    },
                    {
                        id: 'TIMER_PAUSED_ACTIONS',
                        actions: [
                            {
                                id: 'timer_resume',
                                title: 'Resume'
                            },
                            {
                                id: 'timer_stop',
                                title: 'End'
                            }
                        ]
                    }
                ]
            });
            console.log('[FlowTick Notifications] Native channels and action types registered');
        } catch (err) {
            console.warn('[FlowTick Notifications] Channel creation warning:', err);
        }
    }
}

// Request notification permissions for both native Android (Capacitor) and Web
async function requestNotificationPermissions() {
    // 1. Native Capacitor on Android/iOS
    if (window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.LocalNotifications) {
        try {
            const check = await window.Capacitor.Plugins.LocalNotifications.checkPermissions();
            if (check.display === 'granted') {
                await registerNotificationChannels();
                return true;
            }
            const request = await window.Capacitor.Plugins.LocalNotifications.requestPermissions();
            await registerNotificationChannels();
            const granted = (request.display === 'granted');
            if (granted) {
                showToast('Notifications enabled on your device!', 'success');
            }
            return granted;
        } catch (err) {
            console.error('[FlowTick Notifications] Native permission request failed:', err);
        }
    }

    // 2. Web browser fallback
    if ("Notification" in window) {
        if (Notification.permission === 'default') {
            try {
                const perm = await Notification.requestPermission();
                return perm === 'granted';
            } catch (e) {
                return false;
            }
        }
        return Notification.permission === 'granted';
    }
    return false;
}

window.registerNotificationChannels = registerNotificationChannels;
window.requestNotificationPermissions = requestNotificationPermissions;

async function handleCompleteTaskAction(itemId, itemType, notifTitle) {
    try {
        const tasks = await getTasksFromFirebase();
        const item = tasks.find(t => String(t.id) === String(itemId));
        if (item) {
            if (typeof window.toggleItemComplete === 'function') {
                window.toggleItemComplete(itemId, false);
            } else {
                item.isCompleted = true;
                item.completedAt = new Date().toISOString();
                await saveTaskToFirebase(item);
                displayTasks();
            }
            showToast(`"${item.title}" marked as complete!`, 'success');
        } else {
            const cleanTitle = (notifTitle || '').replace('Reminder: ', '').replace('Task Overdue: ', '').replace("It's time for: ", '');
            const taskByTitle = tasks.find(t => t.title === cleanTitle && !t.isCompleted && !t.isCancelled);
            if (taskByTitle) {
                if (typeof window.toggleItemComplete === 'function') {
                    window.toggleItemComplete(taskByTitle.id, false);
                } else {
                    taskByTitle.isCompleted = true;
                    taskByTitle.completedAt = new Date().toISOString();
                    await saveTaskToFirebase(taskByTitle);
                    displayTasks();
                }
                showToast(`"${taskByTitle.title}" marked as complete!`, 'success');
            }
        }
    } catch (e) {
        console.error('[FlowTick Notifications] Error handling complete action:', e);
    }
}

async function handleCancelTaskAction(itemId, itemType, notifTitle) {
    try {
        const tasks = await getTasksFromFirebase();
        const item = tasks.find(t => String(t.id) === String(itemId));
        if (item) {
            if (item.type === 'habit') {
                if (typeof window.skipHabitInDetails === 'function') {
                    window.skipHabitInDetails(itemId);
                } else {
                    const todayStr = getTodayStr();
                    if (!item.skippedDates) item.skippedDates = [];
                    if (!item.skippedDates.includes(todayStr)) item.skippedDates.push(todayStr);
                    await saveTaskToFirebase(item);
                    displayTasks();
                }
                showToast(`"${item.title}" skipped for today`, 'info');
            } else {
                if (typeof window.cancelItem === 'function') {
                    window.cancelItem(itemId);
                } else {
                    item.isCancelled = true;
                    item.isCompleted = false;
                    await saveTaskToFirebase(item);
                    displayTasks();
                }
                showToast(`"${item.title}" marked as Won't Do`, 'info');
            }
        }
    } catch (e) {
        console.error('[FlowTick Notifications] Error handling cancel action:', e);
    }
}

function initNotificationActionListeners() {
    if (!window.Capacitor || !window.Capacitor.Plugins || !window.Capacitor.Plugins.LocalNotifications) {
        return;
    }

    if (window._notifActionListenerInitialized) return;
    window._notifActionListenerInitialized = true;

    window.Capacitor.Plugins.LocalNotifications.addListener('localNotificationActionPerformed', async (action) => {
        console.log('[FlowTick Notifications] Action performed:', action);
        const actionId = action.actionId;
        const notification = action.notification || {};
        const extra = notification.extra || {};
        const itemId = extra.itemId;
        const itemType = extra.itemType || 'task';

        // Timer actions
        if (notification.id === 888888) {
            if (actionId === 'timer_pause') {
                if (typeof window.pausePomodoro === 'function') {
                    window.pausePomodoro();
                }
            } else if (actionId === 'timer_resume') {
                if (typeof window.resumePomodoro === 'function') {
                    window.resumePomodoro();
                }
            } else if (actionId === 'timer_stop') {
                if (typeof window.resetPomodoro === 'function') {
                    window.resetPomodoro();
                }
            } else if (actionId === 'tap') {
                if (typeof window.navigateToPage === 'function') {
                    window.navigateToPage('pomodoro-page', true);
                }
                if (typeof window.syncTimerWithTimePassed === 'function') {
                    window.syncTimerWithTimePassed();
                }
            }
            return;
        }

        // Task & Habit actions
        if (actionId === 'mark_done' && itemId) {
            handleCompleteTaskAction(itemId, itemType, notification.title);
        } else if (actionId === 'wont_do' && itemId) {
            handleCancelTaskAction(itemId, itemType, notification.title);
        } else if (actionId === 'tap') {
            if (itemId && typeof window.showItemDetails === 'function') {
                window.showItemDetails(itemId);
            }
        }
    });
}

window.handleCompleteTaskAction = handleCompleteTaskAction;
window.handleCancelTaskAction = handleCancelTaskAction;
window.initNotificationActionListeners = initNotificationActionListeners;

// Pre-register channels and action listeners immediately and on load
registerNotificationChannels();
initNotificationActionListeners();
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        registerNotificationChannels();
        initNotificationActionListeners();
    });
} else {
    registerNotificationChannels();
    initNotificationActionListeners();
}

function getNextOccurrenceTime(startDateStr, startTimeStr, frequency, specificDays, customNum, customUnit, relativeToNow = true) {
    let triggerTime = parseLocalISOString(startDateStr, startTimeStr || '09:00');
    if (!triggerTime) return null;

    const compareTime = relativeToNow ? new Date() : new Date(triggerTime.getTime());
    if (relativeToNow && triggerTime > compareTime) {
        return triggerTime;
    }

    let maxIterations = 1000;
    let iterations = 0;

    if (frequency === 'daily') {
        while (triggerTime <= compareTime && iterations < maxIterations) {
            triggerTime.setDate(triggerTime.getDate() + 1);
            iterations++;
        }
    } else if (frequency === 'weekly') {
        while (triggerTime <= compareTime && iterations < maxIterations) {
            triggerTime.setDate(triggerTime.getDate() + 7);
            iterations++;
        }
    } else if (frequency === 'monthly') {
        while (triggerTime <= compareTime && iterations < maxIterations) {
            triggerTime.setMonth(triggerTime.getMonth() + 1);
            iterations++;
        }
    } else if (frequency === 'yearly') {
        while (triggerTime <= compareTime && iterations < maxIterations) {
            triggerTime.setFullYear(triggerTime.getFullYear() + 1);
            iterations++;
        }
    } else if (frequency === 'custom') {
        const num = customNum || 1;
        const unit = customUnit || 'days';
        while (triggerTime <= compareTime && iterations < maxIterations) {
            if (unit === 'days') {
                triggerTime.setDate(triggerTime.getDate() + num);
            } else if (unit === 'weeks') {
                if (specificDays && specificDays.length > 0) {
                    let foundNext = false;
                    for (let dayOffset = 1; dayOffset < 365; dayOffset++) {
                        let testTime = new Date(triggerTime.getTime());
                        testTime.setDate(testTime.getDate() + dayOffset);
                        if (specificDays.includes(testTime.getDay()) && testTime > compareTime) {
                            triggerTime = testTime;
                            foundNext = true;
                            break;
                        }
                    }
                    if (!foundNext) {
                        triggerTime.setDate(triggerTime.getDate() + num * 7);
                    }
                } else {
                    triggerTime.setDate(triggerTime.getDate() + num * 7);
                }
            } else if (unit === 'months') {
                triggerTime.setMonth(triggerTime.getMonth() + num);
            } else if (unit === 'years') {
                triggerTime.setFullYear(triggerTime.getFullYear() + num);
            }
            iterations++;
        }
    } else if (specificDays && specificDays.length > 0) {
        let foundNext = false;
        for (let dayOffset = 1; dayOffset < 365; dayOffset++) {
            let testTime = new Date(triggerTime.getTime());
            testTime.setDate(testTime.getDate() + dayOffset);
            if (specificDays.includes(testTime.getDay()) && testTime > compareTime) {
                triggerTime = testTime;
                foundNext = true;
                break;
            }
        }
        if (!foundNext) {
            triggerTime.setDate(triggerTime.getDate() + 1);
        }
    }

    return triggerTime;
}

function getMissedNotificationsKey() {
    const currentUser = JSON.parse(localStorage.getItem('currentUser'));
    const currentUserId = currentUser ? currentUser.id : 'guest';
    return `missedNotifications_${currentUserId}`;
}

function addMissedNotification(title, time24, category = 'reminder') {
    const key = getMissedNotificationsKey();
    let list = JSON.parse(localStorage.getItem(key)) || [];
    list.unshift({
        id: Date.now(),
        title: title,
        category: category,
        time: formatTaskTimeDisplay(time24),
        timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    });
    localStorage.setItem(key, JSON.stringify(list));
    localStorage.setItem('notificationsSeen', 'false'); // Mark as unseen
    renderMissedNotifications();
}

function deleteMissedNotification(id) {
    const key = getMissedNotificationsKey();
    let list = JSON.parse(localStorage.getItem(key)) || [];
    list = list.filter(n => n.id !== id);
    localStorage.setItem(key, JSON.stringify(list));
    renderMissedNotifications();
}

function completeNotifTask(event, notifId, taskTitle) {
    if (event) event.stopPropagation();
    
    // 1. Delete from notifications list
    deleteMissedNotification(notifId);

    // 2. Complete task in Firestore
    getTasksFromFirebase().then(tasks => {
        const task = tasks.find(t => t.title === taskTitle && !t.isCompleted && !t.isCancelled);
        if (task) {
            task.isCompleted = true;
            task.completedAt = new Date().toISOString();
            saveTaskToFirebase(task).then(() => {
                showToast(`"${task.title}" marked as complete!`, 'success');
                displayTasks();
                if (window.calendarInstance) window.calendarInstance.refetchEvents();
            });
        } else {
            showToast('Task already completed or not found.', 'info');
        }
    });
}

function cancelNotifTask(event, notifId, taskTitle) {
    if (event) event.stopPropagation();
    
    // 1. Delete from notifications list
    deleteMissedNotification(notifId);

    // 2. Cancel task in Firestore
    getTasksFromFirebase().then(tasks => {
        const task = tasks.find(t => t.title === taskTitle && !t.isCompleted && !t.isCancelled);
        if (task) {
            task.isCancelled = true;
            task.isCompleted = false;
            saveTaskToFirebase(task).then(() => {
                showToast(`"${task.title}" marked as Won't Do`, 'info');
                displayTasks();
                if (window.calendarInstance) window.calendarInstance.refetchEvents();
            });
        } else {
            showToast('Task already completed or not found.', 'info');
        }
    });
}

// Bind missed actions globally for inline dynamic HTML click handlers
window.deleteMissedNotification = deleteMissedNotification;
window.completeNotifTask = completeNotifTask;
window.cancelNotifTask = cancelNotifTask;

function renderMissedNotifications() {
    const badge = document.getElementById('notification-badge');
    const listEl = document.getElementById('notif-list');
    if (!badge || !listEl) return;

    const key = getMissedNotificationsKey();
    const list = JSON.parse(localStorage.getItem(key)) || [];
    const isSeen = localStorage.getItem('notificationsSeen') === 'true';

    if (list.length > 0) {
        badge.textContent = list.length;
        badge.style.display = isSeen ? 'none' : 'inline-flex';
        
        let html = '';
        list.forEach(n => {
            const plainTitle = n.title.replace('Overdue: ', '').replace('Reminder: ', '');
            
            // Dynamic theme variables for circular check button
            const completeColor = n.category === 'overdue' ? '#73D13D' : 'var(--color-ticktick-blue)';
            const completeBg = n.category === 'overdue' ? 'rgba(115,209,61,0.15)' : 'rgba(47,123,246,0.1)';

            let actionButtonsHTML = `
                <div class="notif-actions" style="margin-top: 6px; display: flex; gap: 8px; align-items: center;">
                    <button class="notif-action-btn" onclick="completeNotifTask(event, ${n.id}, '${plainTitle.replace(/'/g, "\\'")}')" title="Mark Done" style="background:${completeBg}; color:${completeColor}; border:none; width: 28px; height: 28px; border-radius:50%; display: flex; align-items:center; justify-content:center; font-size:12px; cursor:pointer; transition:0.2s;"><i class="fa-solid fa-check"></i></button>
                    <button class="notif-action-btn" onclick="cancelNotifTask(event, ${n.id}, '${plainTitle.replace(/'/g, "\\'")}')" title="Won't Do" style="background:rgba(255,77,79,0.1); color:#FF4D4F; border:none; width: 28px; height: 28px; border-radius:50%; display: flex; align-items:center; justify-content:center; font-size:12px; cursor:pointer; transition:0.2s;"><i class="fa-solid fa-ban"></i></button>
                </div>
            `;

            html += `
                <div class="notif-item" style="padding: 12px 16px; border-bottom: 1px solid var(--border-color); display: flex; flex-direction: column; gap: 4px;">
                    <div style="display: flex; justify-content: space-between; align-items: flex-start; width: 100%;">
                        <div class="notif-content" style="display: flex; flex-direction: column; gap: 2px;">
                            <span class="notif-title" style="font-size: 13.5px; font-weight: 600; color: var(--text-main);">${n.title}</span>
                            <span class="notif-time" style="font-size: 11px; color: var(--text-muted);">${n.timestamp}</span>
                        </div>
                        <button class="btn-delete-notif" onclick="deleteMissedNotification(${n.id})" style="background:none; border:none; color:var(--text-muted); cursor:pointer; font-size: 14px;"><i class="fa-solid fa-xmark"></i></button>
                    </div>
                    ${actionButtonsHTML}
                </div>
            `;
        });
        listEl.innerHTML = html;
    } else {
        badge.style.display = 'none';
        listEl.innerHTML = '<div class="no-notif">No missed notifications</div>';
    }
}

function initMissedNotificationsUI() {
    const notifBtn = document.getElementById('notification-btn');
    const dropdown = document.getElementById('notification-dropdown');
    const clearBtn = document.getElementById('clear-notifications-btn');

    if (!notifBtn || !dropdown) return;

    notifBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        dropdown.classList.toggle('active');

        // Mark as seen when the dropdown is opened
        if (dropdown.classList.contains('active')) {
            localStorage.setItem('notificationsSeen', 'true');
            renderMissedNotifications();
        }

        // Request permission on bell click if not granted
        requestNotificationPermissions();
    });

    document.addEventListener('click', () => {
        dropdown.classList.remove('active');
    });

    dropdown.addEventListener('click', (e) => {
        e.stopPropagation();
    });

    if (clearBtn) {
        clearBtn.addEventListener('click', () => {
            const key = getMissedNotificationsKey();
            localStorage.setItem(key, JSON.stringify([]));
            renderMissedNotifications();
        });
    }

    renderMissedNotifications();
}

function scheduleMobileNotification(id, title, body, triggerTime, frequency, soundName, extraData = null, actionTypeId = null) {
    const triggerTimestamp = triggerTime instanceof Date ? triggerTime.getTime() : new Date(triggerTime).getTime();
    const now = Date.now();
    const delayMs = triggerTimestamp - now;

    // Overdue by more than 2 minutes and not recurring -> mark as missed
    if (delayMs <= -120000 && !frequency) {
        console.log(`[MobileBridge] Notification missed (${Math.abs(delayMs)}ms ago). Adding to missed list.`);
        const tDate = new Date(triggerTimestamp);
        const hours = String(tDate.getHours()).padStart(2, '0');
        const mins = String(tDate.getMinutes()).padStart(2, '0');
        addMissedNotification(`Overdue: ${title}`, `${hours}:${mins}`, 'overdue');
        return;
    }

    // Safe 32-bit positive integer ID for Android AlarmManager & NotificationManager
    let notifId = parseInt(id, 10);
    if (isNaN(notifId)) {
        notifId = Math.abs(String(id).split("").reduce((a, b) => { a = ((a << 5) - a) + b.charCodeAt(0); return a & a; }, 0));
    }
    notifId = (Math.abs(notifId) % 2000000000) + 1;

    const sound = soundName || 'success.mp3';
    const soundBase = sound.replace(/\.[^/.]+$/, "");
    const channelId = `flowtick-${soundBase}-channel-v6`;

    // Anything within 1000ms or already slightly passed is IMMEDIATE
    const isImmediate = delayMs <= 1000 && !frequency;

    if (window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.LocalNotifications) {
        registerNotificationChannels();

        const notifItem = {
            id: notifId,
            title: title,
            body: body,
            sound: soundBase,
            channelId: channelId,
            ongoing: false,
            autoCancel: true
        };

        if (actionTypeId) {
            notifItem.actionTypeId = actionTypeId;
        } else if (extraData && extraData.itemId) {
            notifItem.actionTypeId = 'TASK_ACTIONS';
        }

        if (extraData) {
            notifItem.extra = extraData;
        }

        if (!isImmediate) {
            const scheduleOpts = {
                at: new Date(triggerTimestamp),
                allowWhileIdle: true
            };
            if (frequency === 'daily') {
                scheduleOpts.repeats = true;
                scheduleOpts.every = 'day';
            } else if (frequency === 'weekly') {
                scheduleOpts.repeats = true;
                scheduleOpts.every = 'week';
            } else if (frequency === 'monthly') {
                scheduleOpts.repeats = true;
                scheduleOpts.every = 'month';
            } else if (frequency === 'yearly') {
                scheduleOpts.repeats = true;
                scheduleOpts.every = 'year';
            }
            notifItem.schedule = scheduleOpts;
        }

        window.Capacitor.Plugins.LocalNotifications.schedule({
            notifications: [notifItem]
        }).then(() => {
            console.log(`[MobileBridge] Scheduled #${notifId} ("${title}") ${isImmediate ? 'IMMEDIATE' : 'at ' + new Date(triggerTimestamp).toISOString()}`);
        }).catch(err => {
            console.error("[MobileBridge] Schedule error:", err);
            if (String(err).includes('not enabled') || String(err).includes('permission')) {
                requestNotificationPermissions();
            }
        });

        return;
    }

    // Web Fallback (Laptop/Browser)
    console.log(`[MobileBridge] Web fallback. Delay: ${delayMs}ms, isImmediate: ${isImmediate}`);
    if (window.Notification && Notification.permission === "default") {
        Notification.requestPermission();
    }

    if (isImmediate) {
        if (typeof playSound === 'function') {
            playSound(soundBase === 'pomodoro' ? 'pomodoro' : 'success');
        }
        if (window.Notification && Notification.permission === "granted") {
            new Notification(title, { body: body });
        } else {
            showToast(`${title}: ${body}`, 'info');
        }
    } else if (delayMs > 0) {
        setTimeout(() => {
            if (typeof playSound === 'function') {
                playSound(soundBase === 'pomodoro' ? 'pomodoro' : 'success');
            }
            if (window.Notification && Notification.permission === "granted") {
                new Notification(title, { body: body });
            } else {
                showToast(`${title}: ${body}`, 'info');
            }
        }, delayMs);
    }
}

function updateMobileTimerNotification(isWork, timeLeft, isRunning = true, expectedEnd = null) {
    if (window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.LocalNotifications) {
        registerNotificationChannels();
        const mins = Math.floor(timeLeft / 60);
        const secs = timeLeft % 60;
        const timeStr = `${mins}:${String(secs).padStart(2, '0')} remaining`;

        const actionTypeId = isRunning ? 'TIMER_RUNNING_ACTIONS' : 'TIMER_PAUSED_ACTIONS';
        const title = isWork 
            ? (isRunning ? '🍅 Focus Session Active' : '⏸️ Focus Session Paused')
            : (isRunning ? '☕ Break Session Active' : '⏸️ Break Session Paused');

        const notif = {
            id: 888888,
            title: title,
            body: timeStr,
            channelId: 'flowtick-timer-live-v6',
            ongoing: true, // Pinned in notification drawer
            autoCancel: false,
            actionTypeId: actionTypeId,
            extra: {
                isWorkSession: isWork,
                timeLeft: timeLeft,
                isRunning: isRunning
            }
        };

        if (isRunning && expectedEnd) {
            notif.extra.chronometer = expectedEnd;
        }

        window.Capacitor.Plugins.LocalNotifications.schedule({
            notifications: [notif]
        }).catch(err => {
            console.warn('[LiveTimer] Update notification error:', err);
        });
    }
}

function cancelMobileNotification(id) {
    let notifId = parseInt(id, 10);
    if (isNaN(notifId)) {
        notifId = Math.abs(String(id).split("").reduce((a, b) => { a = ((a << 5) - a) + b.charCodeAt(0); return a & a; }, 0));
    }
    notifId = (Math.abs(notifId) % 2000000000) + 1;

    if (window.AndroidBridge && typeof window.AndroidBridge.cancelNotification === 'function') {
        window.AndroidBridge.cancelNotification(String(notifId));
        return;
    }
    if (window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.LocalNotifications) {
        window.Capacitor.Plugins.LocalNotifications.cancel({
            notifications: [{ id: notifId }]
        }).catch(err => console.warn('[MobileBridge] Cancel error:', err));
        return;
    }
    if (window.cordova && window.cordova.plugins && window.cordova.plugins.notification && window.cordova.plugins.notification.local) {
        window.cordova.plugins.notification.local.cancel(notifId);
        return;
    }
}

// Bind globally for backward compatibility / external library hooks
window.scheduleMobileNotification = scheduleMobileNotification;
window.updateMobileTimerNotification = updateMobileTimerNotification;
window.cancelMobileNotification = cancelMobileNotification;

function scheduleItemNotifications(item) {
    if (!item) return;

    // Generate clean unique numeric IDs
    const numericId = getStableNumericId(item.id);
    const dueNumericId = getStableNumericId(item.id) + 999999; 

    // Cancel old notifications to prevent duplicates (including multi-timers)
    cancelMobileNotification(numericId);
    cancelMobileNotification(dueNumericId);
    for (let i = 1; i <= 10; i++) {
        cancelMobileNotification(numericId + (i * 1000));
    }

    if (item.isCancelled || item.isDeleted) return;

    const isRepeating = (item.type === 'habit' || (item.frequency && item.frequency !== 'none'));
    if (item.isCompleted && !isRepeating) return;

    // Habit multiple reminder timers or single start time
    const habitTimers = (item.type === 'habit' && Array.isArray(item.reminderTimes) && item.reminderTimes.length > 0)
        ? item.reminderTimes
        : (item.startTime ? [item.startTime] : []);

    if (item.startDate && habitTimers.length > 0) {
        habitTimers.forEach((timeStr, idx) => {
            const subNotifId = idx === 0 ? numericId : numericId + (idx * 1000);
            let triggerTime;
            if (isRepeating) {
                const now = new Date();
                const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
                
                const isCompletedToday = item.isCompleted || (item.completedDates && item.completedDates.includes(todayStr));
                let startFromDate = item.startDate;
                if (isCompletedToday) {
                    const tomorrow = new Date();
                    tomorrow.setDate(tomorrow.getDate() + 1);
                    startFromDate = `${tomorrow.getFullYear()}-${String(tomorrow.getMonth() + 1).padStart(2, '0')}-${String(tomorrow.getDate()).padStart(2, '0')}`;
                }
                triggerTime = getNextOccurrenceTime(startFromDate, timeStr, item.frequency, item.specificDays, item.customNum, item.customUnit);
            } else {
                triggerTime = parseLocalISOString(item.startDate, timeStr);
            }

            if (triggerTime && triggerTime > new Date()) {
                let notifTitle = 'Task Reminder';
                let notifBody = `It's time for: ${item.title}`;
                if (item.type === 'event') {
                    notifTitle = 'Event Reminder';
                    notifBody = `Event starting: ${item.title}`;
                } else if (item.type === 'habit') {
                    notifTitle = 'Habit Reminder';
                    notifBody = `Time for your habit: ${item.title}`;
                }

                scheduleMobileNotification(
                    subNotifId,
                    notifTitle,
                    notifBody,
                    triggerTime,
                    null,
                    'success.mp3',
                    { itemId: item.id, itemType: item.type || 'task' },
                    'TASK_ACTIONS'
                );
            }
        });
    }

    // Schedule Deadline (Due Date) if defined
    if (item.dueDate && item.dueTime) {
        const triggerTime = parseLocalISOString(item.dueDate, item.dueTime);
        if (triggerTime && triggerTime > new Date()) {
            scheduleMobileNotification(
                dueNumericId,
                'Task Overdue!',
                `The deadline for "${item.title}" has passed.`,
                triggerTime,
                null,
                'success.mp3',
                { itemId: item.id, itemType: item.type || 'task' },
                'TASK_ACTIONS'
            );
        }
    }
}

window.scheduleItemNotifications = scheduleItemNotifications;


/* ===== js/auth.js ===== */
function togglePasswordVisibility(inputId, iconEl) {
    const input = document.getElementById(inputId);
    if (!input) return;
    if (input.type === 'password') {
        input.type = 'text';
        iconEl.classList.remove('fa-eye-slash');
        iconEl.classList.add('fa-eye');
    } else {
        input.type = 'password';
        iconEl.classList.remove('fa-eye');
        iconEl.classList.add('fa-eye-slash');
    }
}

function closeAuthScreen(event) {
    if (event) event.preventDefault();
    localStorage.setItem('isGuestMode', 'true');
    const authScreen = document.getElementById('auth-screen');
    const appScreen = document.getElementById('app-screen');
    if (authScreen) authScreen.style.display = 'none';
    if (appScreen) appScreen.style.display = 'flex';
    displayTasks();
    if (window.calendarInstance) window.calendarInstance.refetchEvents();
    initSettings();
}

function toggleAuth(type) {
    const loginForm = document.getElementById('login-form');
    const signupForm = document.getElementById('signup-form');
    if (type === 'signup') {
        if (loginForm) loginForm.style.display = 'none';
        if (signupForm) signupForm.style.display = 'block';
    } else {
        if (loginForm) loginForm.style.display = 'block';
        if (signupForm) signupForm.style.display = 'none';
    }
}

window.togglePasswordVisibility = togglePasswordVisibility;
window.closeAuthScreen = closeAuthScreen;
window.toggleAuth = toggleAuth;

function initAuth() {
    const authScreen = document.getElementById('auth-screen');
    const appScreen = document.getElementById('app-screen');
    const loginForm = document.getElementById('login-form');
    const signupForm = document.getElementById('signup-form');
    const logoutBtn = document.getElementById('logout-btn');
    const loginSidebarBtn = document.getElementById('login-sidebar-btn');

    // Programmatic event listeners for password eye toggles
    document.querySelectorAll('.toggle-password-icon').forEach(icon => {
        icon.addEventListener('click', () => {
            const targetId = icon.getAttribute('data-toggle');
            if (targetId) {
                togglePasswordVisibility(targetId, icon);
            }
        });
    });

    // Programmatic event listeners for continue as guest buttons
    document.querySelectorAll('.continue-guest-btn').forEach(btn => {
        btn.addEventListener('click', (e) => {
            closeAuthScreen(e);
        });
    });

    // Programmatic event listeners for auth form switch links
    document.querySelectorAll('.auth-toggle-link').forEach(link => {
        link.addEventListener('click', () => {
            const target = link.getAttribute('data-auth-target');
            if (target) {
                toggleAuth(target);
            }
        });
    });

    // Login Sidebar Button handler
    if (loginSidebarBtn) {
        loginSidebarBtn.addEventListener('click', () => {
            authScreen.style.display = 'flex';
            appScreen.style.display = 'none';
        });
    }

    // Register Firebase Auth State Listener
    onAuthStateChanged(auth, (user) => {
        if (user) {
            // User is signed in
            const currentUser = {
                id: user.uid,
                email: user.email,
                name: user.displayName || user.email.split('@')[0]
            };
            localStorage.setItem('currentUser', JSON.stringify(currentUser));
            localStorage.removeItem('isGuestMode');
            
            authScreen.style.display = 'none';
            appScreen.style.display = 'flex';
            document.getElementById('display-username').textContent = currentUser.name;
            const dTitle = document.getElementById('dashboard-title');
            if (dTitle) dTitle.textContent = `Hello, ${currentUser.name}`;
            
            if (logoutBtn) logoutBtn.style.display = 'block';
            if (loginSidebarBtn) loginSidebarBtn.style.display = 'none';

            // Sync Guest tasks if any
            Promise.resolve().then(() => {
                syncGuestDataToFirebase(user.uid);
            });
            
            displayTasks();
            if (window.calendarInstance) window.calendarInstance.refetchEvents();
            initSettings();
        } else {
            // User is signed out
            localStorage.removeItem('currentUser');
            
            const justLoggedOut = localStorage.getItem('justLoggedOut');
            const isGuestMode = localStorage.getItem('isGuestMode') === 'true';

            if (justLoggedOut === 'true') {
                localStorage.removeItem('justLoggedOut');
                localStorage.removeItem('isGuestMode');
                authScreen.style.display = 'flex';
                appScreen.style.display = 'none';
            } else if (isGuestMode) {
                authScreen.style.display = 'none';
                appScreen.style.display = 'flex';
            } else {
                authScreen.style.display = 'flex';
                appScreen.style.display = 'none';
            }
            
            const guestName = localStorage.getItem('guestName') || 'Guest User';
            document.getElementById('display-username').textContent = guestName;
            const dTitle = document.getElementById('dashboard-title');
            if (dTitle) dTitle.textContent = `Hello, ${guestName}`;
            
            if (logoutBtn) logoutBtn.style.display = 'none';
            if (loginSidebarBtn) loginSidebarBtn.style.display = 'block';

            displayTasks();
            if (window.calendarInstance) window.calendarInstance.refetchEvents();
            initSettings();
        }
    });

    // Forms event handlers
    signupForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const name = document.getElementById('signup-name').value;
        const email = document.getElementById('signup-email').value;
        const password = document.getElementById('signup-password').value;
        const confirmPassword = document.getElementById('signup-confirm-password').value;

        if (password !== confirmPassword) {
            showToast('Passwords do not match!', 'error');
            return;
        }

        createUserWithEmailAndPassword(auth, email, password)
            .then((userCredential) => {
                const user = userCredential.user;
                return updateProfile(user, { displayName: name });
            })
            .then(() => {
                showToast('Account created successfully!', 'success');
            })
            .catch((error) => {
                showToast(error.message, 'error');
            });
    });

    loginForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const email = document.getElementById('login-email').value;
        const password = document.getElementById('login-password').value;

        signInWithEmailAndPassword(auth, email, password)
            .then((userCredential) => {
                showToast('Logged in successfully!', 'success');
            })
            .catch((error) => {
                showToast('Invalid email or password!', 'error');
            });
    });

    logoutBtn.addEventListener('click', () => {
        localStorage.setItem('justLoggedOut', 'true');
        signOut(auth).then(() => {
            showToast('Logged out successfully', 'info');
        }).catch((error) => console.error(error));
    });

    const forgotPassLink = document.getElementById('forgot-password-link');
    if (forgotPassLink) {
        forgotPassLink.addEventListener('click', (e) => {
            e.preventDefault();
            const emailInput = document.getElementById('login-email').value;
            
            if (!emailInput) {
                showToast('Please enter your email address first!', 'info');
                document.getElementById('login-email').focus();
                return;
            }

            sendPasswordResetEmail(auth, emailInput)
                .then(() => {
                    showToast('Reset email sent! Please check your Inbox and Spam/Junk folder.', 'success');
                })
                .catch((error) => {
                    console.error("Firebase Password Reset Error:", error);
                    showToast('Failed to send reset link: ' + error.message, 'error');
                });
        });
    }
}


/* ===== js/calendar.js ===== */
function initCalendar() {
    const calendarEl = document.getElementById('calendar-placeholder');
    if (!calendarEl) return;

    const is12h = (localStorage.getItem('timeFormat') || '12h') === '12h';

    const calendar = new FullCalendar.Calendar(calendarEl, {
        initialView: 'dayGridMonth',
        direction: 'ltr',
        height: 'auto', 
        stickyHeaderDates: false,
        headerToolbar: { 
            left: 'prev,next today', 
            center: 'title', 
            right: 'dayGridMonth,timeGridWeek,timeGridDay' 
        },
        buttonText: { 
            today: 'Today', 
            month: 'Month', 
            week: 'Week', 
            day: 'Day' 
        },
        slotDuration: '00:30:00',
        displayEventEnd: true,
        eventTimeFormat: {
            hour: 'numeric',
            minute: '2-digit',
            meridiem: is12h ? 'short' : false,
            hour12: is12h
        },
        slotLabelFormat: {
            hour: 'numeric',
            minute: '2-digit',
            meridiem: is12h ? 'short' : false,
            hour12: is12h
        },
        eventClick: function(info) { 
            if (info.event.id) showItemDetails(info.event.id); 
        },
        events: function(info, successCallback, failureCallback) {
            const currentUser = JSON.parse(localStorage.getItem('currentUser'));
            const currentUserId = currentUser ? currentUser.id : 'guest';

            const prefs = JSON.parse(localStorage.getItem('calendarPreferences')) || {
                showTasks: true,
                showEvents: true,
                showHabits: true
            };

            getTasksFromFirebase().then(items => {
                const allEvents = [];
                items.forEach(item => {
                    if (item.userId !== currentUserId) return; 
                    if (item.isDeleted || item.isCancelled) return; 

                    const isTask = (item.type === 'task' || !item.type);
                    const isEvent = (item.type === 'event');
                    const isHabit = (item.type === 'habit');

                    if (isTask && !prefs.showTasks) return;
                    if (isEvent && !prefs.showEvents) return;
                    if (isHabit && !prefs.showHabits) return;

                    let color = getColor(item.priority);
                    if (isEvent) color = 'var(--color-ticktick-blue)';
                    else if (isHabit) color = '#FFA940';
                    
                    let className = item.isCompleted ? 'completed-event' : '';
                    if (item.isCancelled) className = 'cancelled-event';
                    
                    const hasRepeat = item.frequency && item.frequency !== 'none';
                    
                    if (hasRepeat) {
                        let currDate = parseLocalDate(item.startDate);
                        let limitDate = new Date(currDate);
                        limitDate.setMonth(limitDate.getMonth() + 3);
                        if (item.dueDate) {
                            const dueLimit = parseLocalDate(item.dueDate);
                            if (dueLimit < limitDate) {
                                limitDate = dueLimit;
                            }
                        }
                        
                        const startZeroDate = parseLocalDate(item.startDate);
                        
                        while (currDate <= limitDate) {
                            let currentDayOfWeek = currDate.getDay();
                            let shouldRender = false;
                            
                            if (item.frequency === 'daily') {
                                shouldRender = true;
                            } else if (item.frequency === 'weekly') {
                                if (currentDayOfWeek === startZeroDate.getDay()) {
                                    shouldRender = true;
                                }
                            } else if (item.frequency === 'monthly') {
                                if (currDate.getDate() === startZeroDate.getDate()) {
                                    shouldRender = true;
                                }
                            } else if (item.frequency === 'yearly') {
                                if (currDate.getDate() === startZeroDate.getDate() && currDate.getMonth() === startZeroDate.getMonth()) {
                                    shouldRender = true;
                                }
                            } else if (item.frequency === 'custom') {
                                const unit = item.customUnit || 'days';
                                const num = item.customNum || 1;
                                
                                if (unit === 'days') {
                                    const diffTime = Math.abs(currDate - startZeroDate);
                                    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
                                    if (diffDays % num === 0) {
                                        shouldRender = true;
                                    }
                                } else if (unit === 'weeks') {
                                    const startSunday = new Date(startZeroDate);
                                    startSunday.setDate(startSunday.getDate() - startSunday.getDay());
                                    const currSunday = new Date(currDate);
                                    currSunday.setDate(currSunday.getDate() - currSunday.getDay());
                                    const diffTime = Math.abs(currSunday - startSunday);
                                    const diffWeeks = Math.round(diffTime / (1000 * 60 * 60 * 24 * 7));
                                    
                                    if (diffWeeks % num === 0 && item.specificDays && item.specificDays.includes(currentDayOfWeek)) {
                                        shouldRender = true;
                                    }
                                } else if (unit === 'months') {
                                    const monthDiff = (currDate.getFullYear() - startZeroDate.getFullYear()) * 12 + (currDate.getMonth() - startZeroDate.getMonth());
                                    if (monthDiff % num === 0 && currDate.getDate() === startZeroDate.getDate()) {
                                        shouldRender = true;
                                    }
                                }
                            } else if (item.frequency === 'specific_days' && item.specificDays && item.specificDays.includes(currentDayOfWeek)) {
                                shouldRender = true;
                            }
                            
                            if (shouldRender) {
                                let dateStr = formatLocalDate(currDate);
                                let eventStart = dateStr + (item.startTime ? 'T' + (item.startTime.length === 5 ? item.startTime + ':00' : item.startTime) : '');
                                let eventEnd = (isEvent && item.endTime) ? dateStr + 'T' + (item.endTime.length === 5 ? item.endTime + ':00' : item.endTime) : null;
                                allEvents.push({ 
                                    id: item.id, 
                                    title: item.title, 
                                    start: eventStart, 
                                    end: eventEnd,
                                    color: color, 
                                    className: className, 
                                    allDay: !item.startTime 
                                });
                            }
                            currDate.setDate(currDate.getDate() + 1);
                        }
                    } else if (isEvent) {
                        // Events: render as a single event object with accurate start and end ISO strings (NO duplicate looping)
                        let startStr = item.startDate + (item.startTime ? 'T' + (item.startTime.length === 5 ? item.startTime + ':00' : item.startTime) : '');
                        let eventEndDate = item.endDate || item.startDate;
                        let endStr = null;
                        if (item.endTime) {
                            endStr = eventEndDate + 'T' + (item.endTime.length === 5 ? item.endTime + ':00' : item.endTime);
                        } else if (item.endDate && item.endDate !== item.startDate) {
                            endStr = item.endDate;
                        }
                        allEvents.push({ 
                            id: item.id, 
                            title: item.title, 
                            start: startStr, 
                            end: endStr, 
                            color: color, 
                            className: className,
                            allDay: !item.startTime
                        });
                    } else {
                        // Tasks & Habits without repeat
                        let startStr = item.startDate + (item.startTime ? 'T' + (item.startTime.length === 5 ? item.startTime + ':00' : item.startTime) : '');
                        let endStr = null;
                        if (isTask && item.dueDate && item.dueTime) {
                            endStr = item.dueDate + 'T' + (item.dueTime.length === 5 ? item.dueTime + ':00' : item.dueTime);
                        } else if (isTask && item.dueDate && item.dueDate !== item.startDate) {
                            endStr = item.dueDate;
                        }
                        allEvents.push({ 
                            id: item.id, 
                            title: item.title, 
                            start: startStr, 
                            end: endStr, 
                            color: color, 
                            className: className,
                            allDay: !item.startTime
                        });
                    }
                });
                successCallback(allEvents);
            });
        }
    });

    calendar.render();
    window.calendarInstance = calendar;
}


/* ===== js/timer.js ===== */
let sessionMinutes = 25;
let timeLeft = 25 * 60;
let timerInterval = null;
let isRunning = false;
let isWorkSession = true;

// SVG arc circumference: 2π × r where r=75 (the timer circle radius in the SVG).
const ARC_LENGTH = 471.24;
const cx = 120, cy = 120, r = 100;

function updateTimeDisplay() {
    const clockText = document.getElementById('timer-clock');
    const progressPath = document.getElementById('timer-progress');
    const safeTime = Math.max(0, timeLeft);
    const mins = Math.floor(safeTime / 60).toString().padStart(2, '0');
    const secs = (safeTime % 60).toString().padStart(2, '0');
    const newText = `${mins}:${secs}`;
    if (clockText && clockText.textContent !== newText) {
        clockText.textContent = newText;
    }
    if (isRunning && progressPath) {
        const totalSecs = (isWorkSession ? sessionMinutes : Math.round(sessionMinutes / 5)) * 60;
        const ratio = Math.max(0, Math.min(1, safeTime / totalSecs));
        const newOffset = ARC_LENGTH - (ratio * ARC_LENGTH);
        if (progressPath.style.strokeDashoffset !== `${newOffset}`) {
            progressPath.style.strokeDashoffset = newOffset;
        }
    }
}

function updateKnobByMinutes(minutes) {
    if (isRunning) return;
    const knob = document.getElementById('timer-knob');
    const progressPath = document.getElementById('timer-progress');
    const sessionVal = document.getElementById('session-val');
    const breakVal = document.getElementById('break-val');

    sessionMinutes = Math.max(5, Math.min(120, minutes));
    let fraction = (sessionMinutes - 5) / 115;
    let angleDeg = 135 + (fraction * 270);
    let angleRad = angleDeg * Math.PI / 180;
    if (knob) {
        knob.setAttribute('cx', cx + r * Math.cos(angleRad));
        knob.setAttribute('cy', cy + r * Math.sin(angleRad));
    }
    if (progressPath) {
        progressPath.style.strokeDashoffset = ARC_LENGTH - (fraction * ARC_LENGTH);
    }
    if (sessionVal) sessionVal.textContent = sessionMinutes;
    if (breakVal) breakVal.textContent = Math.round(sessionMinutes / 5);
    timeLeft = sessionMinutes * 60;
    updateTimeDisplay();
}

function cancelAllPomodoroNotifications() {
    if (typeof cancelMobileNotification === 'function') {
        cancelMobileNotification(999991);
        cancelMobileNotification(999992);
        cancelMobileNotification(999993);
        cancelMobileNotification(888888);
    }
}

function pausePomodoro() {
    if (!isRunning) return;
    if (timerInterval) {
        clearInterval(timerInterval);
        timerInterval = null;
    }
    isRunning = false;

    const expectedEnd = localStorage.getItem('pomodoro_expected_end');
    if (expectedEnd) {
        const remainingMs = parseInt(expectedEnd, 10) - Date.now();
        timeLeft = Math.max(0, Math.ceil(remainingMs / 1000));
    }
    localStorage.removeItem('pomodoro_expected_end');

    const btnStart = document.getElementById('btn-start-timer');
    if (btnStart) btnStart.innerHTML = '<i class="fa-solid fa-play"></i> Resume';

    if (typeof cancelMobileNotification === 'function') {
        cancelMobileNotification(999991);
        cancelMobileNotification(999992);
        cancelMobileNotification(999993);
    }

    updateTimeDisplay();
    if (typeof updateMobileTimerNotification === 'function') {
        updateMobileTimerNotification(isWorkSession, timeLeft, false, null);
    }
}

function resumePomodoro() {
    if (isRunning || timeLeft <= 0) return;
    isRunning = true;

    const btnStart = document.getElementById('btn-start-timer');
    if (btnStart) btnStart.innerHTML = '<i class="fa-solid fa-pause"></i> Pause';

    const knob = document.getElementById('timer-knob');
    if (knob) knob.style.display = 'none';

    const expectedEnd = Date.now() + (timeLeft * 1000);
    localStorage.setItem('pomodoro_expected_end', expectedEnd);

    if (typeof scheduleMobileNotification === 'function') {
        scheduleMobileNotification(
            999993,
            isWorkSession ? 'Focus Session Finished!' : 'Break Time Finished!',
            isWorkSession ? 'Great focus! Time for a short break.' : 'Break over! Ready to focus on the next task?',
            expectedEnd,
            null,
            'pomodoro.mp3'
        );
    }

    if (typeof updateMobileTimerNotification === 'function') {
        updateMobileTimerNotification(isWorkSession, timeLeft, true, expectedEnd);
    }

    if (timerInterval) clearInterval(timerInterval);
    timerInterval = setInterval(() => {
        syncTimerWithTimePassed();
    }, 200);
}

function resetPomodoro() {
    if (timerInterval) {
        clearInterval(timerInterval);
        timerInterval = null;
    }
    isRunning = false;
    isWorkSession = true;

    const knob = document.getElementById('timer-knob');
    if (knob) knob.style.display = 'block';

    const statusText = document.getElementById('timer-status');
    if (statusText) statusText.innerHTML = '<i class="fa-solid fa-bullseye"></i> Focus';

    const progressPath = document.getElementById('timer-progress');
    if (progressPath) progressPath.style.stroke = 'var(--color-ticktick-blue)';

    const btnStart = document.getElementById('btn-start-timer');
    if (btnStart) btnStart.innerHTML = '<i class="fa-solid fa-play"></i> Start';

    localStorage.removeItem('pomodoro_expected_end');
    cancelAllPomodoroNotifications();
    updateKnobByMinutes(25);
}

window.pausePomodoro = pausePomodoro;
window.resumePomodoro = resumePomodoro;
window.resetPomodoro = resetPomodoro;

function syncTimerWithTimePassed() {
    if (!isRunning) return;
    const expectedEnd = localStorage.getItem('pomodoro_expected_end');
    if (expectedEnd) {
        const remainingMs = parseInt(expectedEnd, 10) - Date.now();
        timeLeft = Math.max(0, Math.ceil(remainingMs / 1000));
        updateTimeDisplay();

        if (timeLeft <= 0) {
            playSound('pomodoro');
            cancelAllPomodoroNotifications();

            const statusText = document.getElementById('timer-status');
            const progressPath = document.getElementById('timer-progress');
            const btnStart = document.getElementById('btn-start-timer');
            const knob = document.getElementById('timer-knob');

            if (isWorkSession) {
                isWorkSession = false;
                if (statusText) statusText.innerHTML = '<i class="fa-solid fa-mug-hot"></i> Break';
                if (progressPath) progressPath.style.stroke = '#73D13D';
                showToast('Focus finished! Break started.', 'info');
                timeLeft = Math.round(sessionMinutes / 5) * 60;
                const nextEnd = Date.now() + (timeLeft * 1000);
                localStorage.setItem('pomodoro_expected_end', nextEnd);

                if (typeof scheduleMobileNotification === 'function') {
                    scheduleMobileNotification(
                        999991,
                        'Focus Session Finished!',
                        'Great focus! Time for a short break.',
                        Date.now() + 100,
                        null,
                        'pomodoro.mp3'
                    );
                    scheduleMobileNotification(
                        999993,
                        'Break Time Finished!',
                        'Break over! Ready to focus on the next task?',
                        nextEnd,
                        null,
                        'pomodoro.mp3'
                    );
                }
                updateTimeDisplay();
                if (typeof updateMobileTimerNotification === 'function') {
                    updateMobileTimerNotification(false, timeLeft, true, nextEnd);
                }
            } else {
                if (timerInterval) {
                    clearInterval(timerInterval);
                    timerInterval = null;
                }
                isRunning = false;
                isWorkSession = true;
                if (statusText) statusText.innerHTML = '<i class="fa-solid fa-bullseye"></i> Focus';
                if (progressPath) progressPath.style.stroke = 'var(--color-ticktick-blue)';
                if (btnStart) btnStart.innerHTML = '<i class="fa-solid fa-play"></i> Start';
                if (knob) knob.style.display = 'block';
                playSound('pomodoro');
                showToast('Break over! Ready to focus?', 'info');
                localStorage.removeItem('pomodoro_expected_end');

                if (typeof cancelMobileNotification === 'function') {
                    cancelMobileNotification(888888);
                    cancelMobileNotification(999993);
                }

                if (typeof scheduleMobileNotification === 'function') {
                    scheduleMobileNotification(
                        999992,
                        'Break Time Finished!',
                        'Break over! Ready to focus on the next task?',
                        Date.now() + 100,
                        null,
                        'pomodoro.mp3'
                    );
                }
                updateKnobByMinutes(sessionMinutes);
            }
        }
    }
}

function initPomodoroDrag() {
    const svgContainer = document.getElementById('svg-container');
    const btnStart = document.getElementById('btn-start-timer');
    const btnReset = document.getElementById('btn-reset-timer');
    const quickBtns = document.querySelectorAll('.quick-time-btn');
    
    const taskSelect = document.getElementById('pomodoro-task-select');
    const taskDoneBtn = document.getElementById('pomodoro-mark-done');

    let isDragging = false;

    if (taskSelect && taskDoneBtn) {
        taskSelect.addEventListener('change', (e) => {
            taskDoneBtn.style.display = e.target.value ? 'block' : 'none';
        });
        taskDoneBtn.addEventListener('click', () => {
            if (taskSelect.value) {
                Promise.resolve().then(() => {
                    toggleItemComplete(taskSelect.value, false);
                });
            }
        });
    }

    if (quickBtns) {
        quickBtns.forEach(btn => {
            btn.addEventListener('click', (e) => {
                if (isRunning) return;
                const mins = parseInt(e.target.getAttribute('data-time'), 10);
                updateKnobByMinutes(mins);
            });
        });
    }

    function handleDrag(e) {
        if (!isDragging || isRunning || !svgContainer) return;
        e.preventDefault();
        let rect = svgContainer.getBoundingClientRect();
        let clientX = e.touches ? e.touches[0].clientX : e.clientX;
        let clientY = e.touches ? e.touches[0].clientY : e.clientY;
        let mouseX = clientX - rect.left;
        let mouseY = clientY - rect.top;
        let angle = Math.atan2(mouseY - cy, mouseX - cx) * 180 / Math.PI;
        if (angle < 0) angle += 360;
        let shifted = angle - 135;
        if (shifted < 0) shifted += 360;
        if (shifted > 270) shifted = shifted > 315 ? 0 : 270;
        let fraction = shifted / 270;
        let mins = 5 + Math.round(fraction * 115 / 5) * 5;
        updateKnobByMinutes(mins);
    }

    if (svgContainer) {
        svgContainer.addEventListener('mousedown', () => { isDragging = true; });
        svgContainer.addEventListener('touchstart', () => { isDragging = true; }, { passive: false });
    }
    window.addEventListener('mousemove', handleDrag);
    window.addEventListener('mouseup', () => { isDragging = false; });
    window.addEventListener('touchmove', handleDrag, { passive: false });
    window.addEventListener('touchend', () => { isDragging = false; });

    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'visible') {
            syncTimerWithTimePassed();
        }
    });
    window.addEventListener('focus', syncTimerWithTimePassed);

    if (btnStart) {
        btnStart.addEventListener('click', () => {
            if (isRunning) {
                pausePomodoro();
            } else {
                resumePomodoro();
            }
        });
    }

    if (btnReset) {
        btnReset.addEventListener('click', () => {
            resetPomodoro();
        });
    }

    updateKnobByMinutes(25);
}


/* ===== js/notes.js ===== */
let activeNoteId = null;
let currentNotesFilter = 'all';
let currentSearchQuery = '';
let autoSaveTimeout = null;

function initNotesUI() {
    const createBtn = document.getElementById('create-note-btn');
    const searchInput = document.getElementById('notes-search-input');
    const closeEditorBtn = document.getElementById('close-note-editor');
    const saveNoteBtn = document.getElementById('save-note-btn');
    const deleteNoteBtn = document.getElementById('delete-note-btn');
    const pinNoteBtn = document.getElementById('note-pin-btn');
    const editorBody = document.getElementById('note-editor-body');
    const titleInput = document.getElementById('note-title-input');

    // Initialize custom dropdowns in Note Editor
    window.customNoteCategorySelect = initCustomSelect('note-category-wrapper', () => {
        triggerAutoSave();
    });

    window.customNoteHeadingSelect = initCustomSelect('note-heading-wrapper', (val) => {
        if (val === 'p') {
            executeFormat('formatBlock', '<p>');
        } else if (val === 'h1' || val === 'h2' || val === 'h3') {
            executeFormat('formatBlock', `<${val}>`);
        }
        if (editorBody) editorBody.focus();
    });

    if (createBtn) {
        createBtn.addEventListener('click', () => openNoteEditor(null));
    }

    if (searchInput) {
        searchInput.addEventListener('input', (e) => {
            currentSearchQuery = e.target.value.toLowerCase().trim();
            renderNotesList();
        });
    }

    if (closeEditorBtn) {
        closeEditorBtn.addEventListener('click', () => closeNoteEditor());
    }

    if (saveNoteBtn) {
        saveNoteBtn.addEventListener('click', () => saveCurrentNote(true));
    }

    if (deleteNoteBtn) {
        deleteNoteBtn.addEventListener('click', () => {
            if (!activeNoteId) {
                closeNoteEditor();
                return;
            }
            showConfirm('Are you sure you want to delete this note?', () => {
                deleteNote(activeNoteId);
                closeNoteEditor();
            });
        });
    }

    if (pinNoteBtn) {
        pinNoteBtn.addEventListener('click', () => {
            pinNoteBtn.classList.toggle('active');
            triggerAutoSave();
        });
    }

    // Auto-save on title or body input
    if (editorBody) {
        editorBody.addEventListener('input', () => {
            updateWordCount();
            triggerAutoSave();
        });

        // Listen for selection changes to highlight active formatting buttons
        editorBody.addEventListener('keyup', updateToolbarStates);
        editorBody.addEventListener('mouseup', updateToolbarStates);
    }

    if (titleInput) {
        titleInput.addEventListener('input', triggerAutoSave);
    }

    // Initialize formatting toolbar buttons
    const formatButtons = document.querySelectorAll('.note-format-btn');
    formatButtons.forEach(btn => {
        btn.addEventListener('mousedown', (e) => {
            // Prevent editor body from losing focus when clicking toolbar
            e.preventDefault();
            const command = btn.getAttribute('data-command');
            const value = btn.getAttribute('data-value') || null;
            executeFormat(command, value);
            updateToolbarStates();
        });
    });



    // Note category filter chips in Notes page
    const filterChips = document.querySelectorAll('.note-filter-chip');
    filterChips.forEach(chip => {
        chip.addEventListener('click', () => {
            filterChips.forEach(c => c.classList.remove('active'));
            chip.classList.add('active');
            currentNotesFilter = chip.getAttribute('data-filter') || 'all';
            renderNotesList();
        });
    });

    window.addEventListener('flowtick-notes-changed', () => {
        renderNotesList();
    });

    // Render initially
    renderNotesList();
}

function executeFormat(command, value = null) {
    const editorBody = document.getElementById('note-editor-body');
    if (!editorBody) return;
    editorBody.focus();

    if (command === 'blockquote') {
        // Toggle blockquote
        const selection = window.getSelection();
        if (selection.rangeCount > 0) {
            const parentBlock = selection.anchorNode.parentElement?.closest('blockquote');
            if (parentBlock) {
                document.execCommand('formatBlock', false, '<p>');
            } else {
                document.execCommand('formatBlock', false, '<blockquote>');
            }
        }
    } else {
        document.execCommand(command, false, value);
    }

    triggerAutoSave();
    updateWordCount();
}

function updateToolbarStates() {
    const formatButtons = document.querySelectorAll('.note-format-btn');
    formatButtons.forEach(btn => {
        const command = btn.getAttribute('data-command');
        if (!command || command === 'formatBlock' || command === 'removeFormat' || command === 'insertHorizontalRule') {
            return;
        }
        try {
            if (document.queryCommandState(command)) {
                btn.classList.add('active');
            } else {
                btn.classList.remove('active');
            }
        } catch (_) {}
    });

    // Check heading level
    if (window.customNoteHeadingSelect) {
        try {
            const parent = window.getSelection()?.anchorNode?.parentElement;
            if (parent) {
                const tag = parent.closest('h1, h2, h3, blockquote, p')?.tagName?.toLowerCase();
                const labels = {
                    'p': '<i class="fa-solid fa-paragraph"></i> Normal',
                    'h1': '<i class="fa-solid fa-heading"></i> Heading 1',
                    'h2': '<i class="fa-solid fa-heading" style="font-size: 11px;"></i> Heading 2',
                    'h3': '<i class="fa-solid fa-heading" style="font-size: 9.5px;"></i> Heading 3'
                };
                if (tag === 'h1' || tag === 'h2' || tag === 'h3') {
                    window.customNoteHeadingSelect.setValue(tag, labels[tag]);
                } else {
                    window.customNoteHeadingSelect.setValue('p', labels['p']);
                }
            }
        } catch (_) {}
    }
}

function updateWordCount() {
    const editorBody = document.getElementById('note-editor-body');
    const countEl = document.getElementById('note-word-count');
    if (!editorBody || !countEl) return;

    const text = editorBody.innerText || '';
    const charCount = text.length;
    const wordCount = text.trim() === '' ? 0 : text.trim().split(/\s+/).length;

    countEl.textContent = `${wordCount} words • ${charCount} chars`;
}

function triggerAutoSave() {
    const statusEl = document.getElementById('note-save-status');
    if (statusEl) {
        statusEl.textContent = 'Unsaved changes';
        statusEl.classList.remove('saved');
    }

    if (autoSaveTimeout) clearTimeout(autoSaveTimeout);
    autoSaveTimeout = setTimeout(() => {
        saveCurrentNote(false);
    }, 1200);
}

async function renderNotesList() {
    const container = document.getElementById('notes-grid');
    if (!container) return;

    const allNotes = await getNotesFromFirebase();
    const currentUser = JSON.parse(localStorage.getItem('currentUser'));
    const currentUserId = currentUser ? currentUser.id : 'guest';

    let userNotes = allNotes.filter(n => n.userId === currentUserId);

    // Apply category filter
    if (currentNotesFilter !== 'all') {
        userNotes = userNotes.filter(n => (n.category || 'General').toLowerCase() === currentNotesFilter.toLowerCase());
    }

    // Apply search query
    if (currentSearchQuery) {
        userNotes = userNotes.filter(n => {
            const titleMatch = (n.title || '').toLowerCase().includes(currentSearchQuery);
            const contentMatch = (n.plainText || '').toLowerCase().includes(currentSearchQuery);
            return titleMatch || contentMatch;
        });
    }

    // Sort: Pinned first, then newest updated
    userNotes.sort((a, b) => {
        if (a.isPinned && !b.isPinned) return -1;
        if (!a.isPinned && b.isPinned) return 1;
        return (b.updatedAt || 0) - (a.updatedAt || 0);
    });

    if (userNotes.length === 0) {
        container.innerHTML = `
            <div class="empty-notes-state" style="grid-column: 1 / -1; text-align: center; padding: 48px 20px; color: var(--text-muted);">
                <div style="font-size: 42px; margin-bottom: 12px; color: var(--color-ticktick-blue); opacity: 0.6;">
                    <i class="fa-regular fa-note-sticky"></i>
                </div>
                <h4 style="font-size: 17px; font-weight: 600; color: var(--text-main); margin-bottom: 6px;">No Notes Found</h4>
                <p style="font-size: 13.5px; max-width: 320px; margin: 0 auto 16px auto;">
                    ${currentSearchQuery ? 'No notes matched your search query.' : 'Capture your thoughts, ideas, plans, and documentation in rich formatted notes.'}
                </p>
                <button onclick="window.openNoteEditor(null)" class="btn btn-primary" style="margin: 0 auto; display: inline-flex; align-items: center; gap: 8px;">
                    <i class="fa-solid fa-plus"></i> Create Note
                </button>
            </div>
        `;
        return;
    }

    container.innerHTML = userNotes.map(note => {
        const catMeta = getCategoryMeta(note.category || 'General');
        const updatedDateStr = formatNoteDate(note.updatedAt || note.createdAt);
        const preview = note.plainText ? escapeHTML(note.plainText.slice(0, 140)) + (note.plainText.length > 140 ? '...' : '') : '<span style="font-style: italic; opacity: 0.6;">Empty note</span>';

        return `
            <div class="note-card ${note.isPinned ? 'pinned' : ''}" onclick="window.openNoteEditor('${note.id}')">
                <div class="note-card-header">
                    <span class="note-category-pill" style="color: ${catMeta.color}; background: ${catMeta.bg};">
                        <i class="fa-solid ${catMeta.icon}"></i> ${escapeHTML(note.category || 'General')}
                    </span>
                    <div class="note-card-actions" onclick="event.stopPropagation();">
                        <button class="btn-icon note-pin-toggle ${note.isPinned ? 'active' : ''}" onclick="window.togglePinNote('${note.id}')" title="${note.isPinned ? 'Unpin Note' : 'Pin Note'}">
                            <i class="fa-solid fa-thumbtack"></i>
                        </button>
                        <button class="btn-icon note-delete-btn" onclick="window.confirmDeleteNote('${note.id}')" title="Delete Note">
                            <i class="fa-solid fa-trash"></i>
                        </button>
                    </div>
                </div>
                <h4 class="note-card-title">${escapeHTML(note.title || 'Untitled Note')}</h4>
                <div class="note-card-preview">${preview}</div>
                <div class="note-card-footer">
                    <span class="note-card-date"><i class="fa-regular fa-clock"></i> ${updatedDateStr}</span>
                </div>
            </div>
        `;
    }).join('');
}

async function openNoteEditor(noteId) {
    activeNoteId = noteId;
    const modal = document.getElementById('note-editor-modal');
    const titleInput = document.getElementById('note-title-input');
    const editorBody = document.getElementById('note-editor-body');
    const categorySelect = document.getElementById('note-category-select');
    const pinBtn = document.getElementById('note-pin-btn');
    const statusEl = document.getElementById('note-save-status');

    if (!modal) return;

    if (noteId) {
        const allNotes = await getNotesFromFirebase();
        const note = allNotes.find(n => String(n.id) === String(noteId));
        if (note) {
            titleInput.value = note.title || '';
            editorBody.innerHTML = note.content || '';
            const cat = note.category || 'Work';
            const catMeta = getCategoryMeta(cat);
            if (window.customNoteCategorySelect) {
                window.customNoteCategorySelect.setValue(cat, `<i class="fa-solid ${catMeta.icon}" style="color:${catMeta.color};"></i> ${catMeta.name}`);
            }
            if (window.customNoteHeadingSelect) {
                window.customNoteHeadingSelect.setValue('p', '<i class="fa-solid fa-paragraph"></i> Normal');
            }
            if (pinBtn) {
                if (note.isPinned) pinBtn.classList.add('active');
                else pinBtn.classList.remove('active');
            }
        }
    } else {
        // New note
        titleInput.value = '';
        editorBody.innerHTML = '';
        const catMeta = getCategoryMeta('Work');
        if (window.customNoteCategorySelect) {
            window.customNoteCategorySelect.setValue('Work', `<i class="fa-solid ${catMeta.icon}" style="color:${catMeta.color};"></i> ${catMeta.name}`);
        }
        if (window.customNoteHeadingSelect) {
            window.customNoteHeadingSelect.setValue('p', '<i class="fa-solid fa-paragraph"></i> Normal');
        }
        if (pinBtn) pinBtn.classList.remove('active');
    }

    if (statusEl) {
        statusEl.textContent = 'Saved';
        statusEl.classList.add('saved');
    }

    updateWordCount();
    modal.classList.add('active');
    setTimeout(() => {
        if (!titleInput.value) titleInput.focus();
        else editorBody.focus();
    }, 150);
}

function closeNoteEditor() {
    if (autoSaveTimeout) {
        clearTimeout(autoSaveTimeout);
        autoSaveTimeout = null;
    }
    const modal = document.getElementById('note-editor-modal');
    if (modal) modal.classList.remove('active');
    activeNoteId = null;
    renderNotesList();
}

async function saveCurrentNote(showFeedback = false) {
    const titleInput = document.getElementById('note-title-input');
    const editorBody = document.getElementById('note-editor-body');
    const categorySelect = document.getElementById('note-category-select');
    const pinBtn = document.getElementById('note-pin-btn');
    const statusEl = document.getElementById('note-save-status');

    if (!titleInput || !editorBody) return;

    const title = titleInput.value.trim();
    const content = editorBody.innerHTML.trim();
    const plainText = editorBody.innerText.trim();

    // If completely empty and new, do not save
    if (!title && !plainText && !activeNoteId) {
        return;
    }

    const category = window.customNoteCategorySelect ? window.customNoteCategorySelect.getValue() : (document.getElementById('note-category-input')?.value || 'Work');
    const isPinned = pinBtn ? pinBtn.classList.contains('active') : false;

    const noteObj = {
        id: activeNoteId,
        title: title || 'Untitled Note',
        content: content,
        plainText: plainText,
        category: category,
        isPinned: isPinned
    };

    const saved = await saveNoteToFirebase(noteObj);
    activeNoteId = saved.id;

    if (statusEl) {
        statusEl.textContent = 'Saved';
        statusEl.classList.add('saved');
    }

    if (showFeedback) {
        showToast('Note saved successfully!', 'success', false);
    }
}

async function deleteNote(noteId) {
    await deleteNoteFromFirebase(noteId);
    showToast('Note deleted', 'info', false);
    renderNotesList();
}

async function togglePinNote(noteId) {
    const allNotes = await getNotesFromFirebase();
    const note = allNotes.find(n => String(n.id) === String(noteId));
    if (note) {
        note.isPinned = !note.isPinned;
        await saveNoteToFirebase(note);
        renderNotesList();
    }
}

function confirmDeleteNote(noteId) {
    showConfirm('Delete this note permanently?', () => {
        deleteNote(noteId);
    });
}

function formatNoteDate(timestamp) {
    if (!timestamp) return '';
    const date = new Date(timestamp);
    const now = new Date();
    const isToday = date.toDateString() === now.toDateString();
    
    const timeStr = date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    if (isToday) return `Today at ${timeStr}`;

    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    if (date.toDateString() === yesterday.toDateString()) {
        return `Yesterday at ${timeStr}`;
    }

    return date.toLocaleDateString([], { month: 'short', day: 'numeric', year: date.getFullYear() !== now.getFullYear() ? 'numeric' : undefined });
}

function escapeHTML(str) {
    if (!str) return '';
    return str.replace(/[&<>'"]/g, tag => ({
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        "'": '&#39;',
        '"': '&quot;'
    }[tag] || tag));
}

// Window attachments for inline onclicks
window.openNoteEditor = openNoteEditor;
window.closeNoteEditor = closeNoteEditor;
window.togglePinNote = togglePinNote;
window.confirmDeleteNote = confirmDeleteNote;


/* ===== js/updates.js ===== */
const GITHUB_REPO_OWNER = 'mohammed-osama187';
const GITHUB_REPO_NAME = 'Personal-Information-Manager';
const DEFAULT_DOWNLOAD_URL = `https://github.com/${GITHUB_REPO_OWNER}/${GITHUB_REPO_NAME}/releases/latest/download/app-release.apk`;
const REMOTE_VERSION_URL = `https://raw.githubusercontent.com/${GITHUB_REPO_OWNER}/${GITHUB_REPO_NAME}/main/version.json`;

function initAppUpdates() {
    const isNative = isNativePlatform();

    // 1. Manage Web-only APK download buttons visibility
    const webDownloadElements = document.querySelectorAll('.web-only-download');
    if (!isNative) {
        webDownloadElements.forEach(el => {
            el.style.display = '';
        });
        // Set dynamic download link
        const sidebarLink = document.getElementById('sidebar-download-link');
        const settingsLink = document.getElementById('settings-download-link');
        if (sidebarLink) sidebarLink.href = DEFAULT_DOWNLOAD_URL;
        if (settingsLink) settingsLink.href = DEFAULT_DOWNLOAD_URL;
    } else {
        webDownloadElements.forEach(el => {
            el.style.display = 'none';
        });
    }

    // 2. App-only Update Check visibility (shown only in mobile app, hidden on website)
    const appUpdateCards = document.querySelectorAll('.app-only-update');
    if (isNative) {
        appUpdateCards.forEach(el => {
            el.style.display = '';
        });
        updateSettingsVersionDisplay();
    } else {
        appUpdateCards.forEach(el => {
            el.style.display = 'none';
        });
    }

    // Settings "Check for Updates" button
    const checkUpdatesBtn = document.getElementById('check-updates-btn');
    if (checkUpdatesBtn) {
        checkUpdatesBtn.addEventListener('click', () => {
            checkAppUpdate(true);
        });
    }

    // 3. Modal action buttons
    const updateCancelBtn = document.getElementById('update-cancel-btn');
    const updateModal = document.getElementById('update-modal');
    if (updateCancelBtn && updateModal) {
        updateCancelBtn.addEventListener('click', () => {
            updateModal.classList.remove('active');
        });
    }

    // 4. If native mobile app, automatically check for updates on startup
    if (isNative) {
        setTimeout(() => {
            checkAppUpdate(false);
        }, 2000);
    }
}

function isNativePlatform() {
    return !!(window.Capacitor && typeof window.Capacitor.isNativePlatform === 'function' && window.Capacitor.isNativePlatform());
}

async function getCurrentAppInfo() {
    try {
        if (window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.App) {
            const info = await window.Capacitor.Plugins.App.getInfo();
            return {
                versionCode: parseInt(info.build, 10) || 1,
                versionName: info.version || '1.0.0'
            };
        }
    } catch (e) {
        console.warn('[Updates] Failed to get native App info:', e);
    }
    return {
        versionCode: 1,
        versionName: '1.0.0'
    };
}

async function updateSettingsVersionDisplay() {
    const versionTextEl = document.getElementById('app-current-version-text');
    if (!versionTextEl) return;
    const appInfo = await getCurrentAppInfo();
    const platformLabel = isNativePlatform() ? 'Android App' : 'Web App';
    versionTextEl.textContent = `${platformLabel} • v${appInfo.versionName} (Build ${appInfo.versionCode})`;
}

async function checkAppUpdate(isManual = false) {
    const checkUpdatesBtn = document.getElementById('check-updates-btn');
    if (checkUpdatesBtn && isManual) {
        checkUpdatesBtn.disabled = true;
        checkUpdatesBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Checking...';
    }

    try {
        const appInfo = await getCurrentAppInfo();
        const currentBuild = appInfo.versionCode;

        // Try remote URL first, then fallback to local version.json
        let latest = null;
        try {
            const remoteRes = await fetch(`${REMOTE_VERSION_URL}?cache_bust=${Date.now()}`);
            if (remoteRes.ok) {
                latest = await remoteRes.json();
            }
        } catch (_) {}

        if (!latest) {
            const localRes = await fetch(`./version.json?cache_bust=${Date.now()}`);
            if (localRes.ok) {
                latest = await localRes.json();
            }
        }

        if (!latest) {
            if (isManual) {
                showToast('Unable to check for updates. Check internet connection.', 'error');
            }
            return;
        }

        const remoteBuild = parseInt(latest.versionCode, 10) || 1;

        if (remoteBuild > currentBuild) {
            showUpdateModal(latest);
        } else {
            if (isManual) {
                showToast(`You are on the latest version (v${appInfo.versionName})`, 'success');
            }
        }
    } catch (error) {
        console.error('[Updates] Update check failed:', error);
        if (isManual) {
            showToast('Update check failed. Please try again.', 'error');
        }
    } finally {
        if (checkUpdatesBtn && isManual) {
            checkUpdatesBtn.disabled = false;
            checkUpdatesBtn.innerHTML = '<i class="fa-solid fa-arrows-rotate"></i> Check for Updates';
        }
    }
}

function showUpdateModal(latest) {
    const modal = document.getElementById('update-modal');
    const versionBadge = document.getElementById('update-version-badge');
    const notesEl = document.getElementById('update-release-notes');
    const confirmBtn = document.getElementById('update-confirm-btn');

    if (!modal) return;

    if (versionBadge) {
        versionBadge.textContent = `v${latest.versionName || '1.1.0'}`;
    }

    if (notesEl) {
        notesEl.textContent = latest.releaseNotes || 'Bug fixes and performance improvements.';
    }

    if (confirmBtn) {
        confirmBtn.onclick = async () => {
            const downloadUrl = latest.downloadUrl || DEFAULT_DOWNLOAD_URL;
            try {
                if (window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.Browser) {
                    await window.Capacitor.Plugins.Browser.open({ url: downloadUrl });
                } else {
                    window.open(downloadUrl, '_blank');
                }
            } catch (e) {
                window.open(downloadUrl, '_blank');
            }
            modal.classList.remove('active');
        };
    }

    modal.classList.add('active');
}

window.checkAppUpdate = checkAppUpdate;


/* ===== js/ui.js ===== */
let tempSubtasks = [];

// Module-level tracker so we can replace the kebab-close handler on each details open
// without accumulating stale listeners on `document`.
let _detailsKebabCloseHandler = null;
let settingsInitialized = false;


// Re-export custom select dropdown helper from utils.js
export { initCustomSelect } from './utils.js';

// ==========================================
// Custom 12h Time Picker component helper
// ==========================================
function initCustomTimePicker(id, isOptional = true, onChange = null) {
    const container = document.getElementById(id);
    if (!container) return null;
    
    const hourDisplay = container.querySelector('.time-hour-display');
    const hourOptions = container.querySelector('.time-hour-options');
    const hourInput = container.querySelector('.time-hour-input');

    const minuteDisplay = container.querySelector('.time-minute-display');
    const minuteOptions = container.querySelector('.time-minute-options');
    const minuteInput = container.querySelector('.time-minute-input');

    const ampmDisplay = container.querySelector('.time-ampm-display');
    const ampmOptions = container.querySelector('.time-ampm-options');
    const ampmInput = container.querySelector('.time-ampm-input');
    const ampmWrapper = container.querySelector('.time-ampm-wrapper');

    function getTimeFormat() {
        return localStorage.getItem('timeFormat') || '12h';
    }

    function rebuildOptions() {
        const is24h = (getTimeFormat() === '24h');
        
        if (ampmWrapper) {
            ampmWrapper.style.display = is24h ? 'none' : 'block';
        }

        let hoursHTML = isOptional ? '<div class="custom-select-option" data-value="">--</div>' : '';
        const maxH = is24h ? 23 : 12;
        const minH = is24h ? 0 : 1;
        for (let h = minH; h <= maxH; h++) {
            const hVal = is24h ? String(h).padStart(2, '0') : String(h);
            hoursHTML += `<div class="custom-select-option" data-value="${hVal}">${hVal}</div>`;
        }
        hourOptions.innerHTML = hoursHTML;

        let minutesHTML = isOptional ? '<div class="custom-select-option" data-value="">--</div>' : '';
        for (let m = 0; m < 60; m++) {
            const val = String(m).padStart(2, '0');
            minutesHTML += `<div class="custom-select-option" data-value="${val}">${val}</div>`;
        }
        minuteOptions.innerHTML = minutesHTML;

        if (!is24h) {
            let ampmHTML = isOptional ? '<div class="custom-select-option" data-value="">--</div>' : '';
            ampmHTML += '<div class="custom-select-option" data-value="AM">AM</div>';
            ampmHTML += '<div class="custom-select-option" data-value="PM">PM</div>';
            ampmOptions.innerHTML = ampmHTML;
        } else {
            if (ampmOptions) ampmOptions.innerHTML = '';
        }
    }

    rebuildOptions();

    function setValue(hour, minute, ampm) {
        const is24h = (getTimeFormat() === '24h');
        
        hourInput.value = hour !== undefined && hour !== null ? String(hour) : '';
        hourDisplay.innerHTML = `${hourInput.value || '--'} <i class="fa-solid fa-chevron-down caret-icon"></i>`;

        minuteInput.value = minute !== undefined && minute !== null ? String(minute).padStart(2, '0') : '';
        minuteDisplay.innerHTML = `${minuteInput.value || '--'} <i class="fa-solid fa-chevron-down caret-icon"></i>`;

        if (!is24h && ampmInput) {
            ampmInput.value = ampm || '';
            ampmDisplay.innerHTML = `${ampm || '--'} <i class="fa-solid fa-chevron-down caret-icon"></i>`;
        } else if (ampmInput) {
            ampmInput.value = '';
            ampmDisplay.innerHTML = '';
        }
    }

    [hourDisplay, minuteDisplay, ampmDisplay].forEach((display) => {
        if (!display) return;
        display.addEventListener('click', (e) => {
            e.stopPropagation();
            const wrapper = display.parentElement;
            const options = wrapper.querySelector('.custom-select-options');
            
            document.querySelectorAll('.custom-select-options.show').forEach(el => {
                if (el !== options) el.classList.remove('show');
            });
            document.querySelectorAll('.custom-select-wrapper.open').forEach(el => {
                if (el !== wrapper) el.classList.remove('open');
            });

            options.classList.toggle('show');
            wrapper.classList.toggle('open');
        });
    });

    container.querySelectorAll('.custom-select-options').forEach(optionsDiv => {
        optionsDiv.addEventListener('click', (e) => {
            const opt = e.target.closest('.custom-select-option');
            if (!opt) return;
            e.stopPropagation();

            const wrapper = optionsDiv.parentElement;
            const display = wrapper.querySelector('.custom-select-display');
            const input = wrapper.querySelector('input[type="hidden"]');
            const val = opt.getAttribute('data-value');

            input.value = val;
            display.innerHTML = `${opt.textContent} <i class="fa-solid fa-chevron-down caret-icon"></i>`;
            
            optionsDiv.classList.remove('show');
            wrapper.classList.remove('open');

            if (val === '') {
                setValue('', '', '');
            } else {
                const is24h = (getTimeFormat() === '24h');
                if (!is24h) {
                    if (wrapper.classList.contains('time-hour-wrapper') && ampmInput && !ampmInput.value) {
                        ampmInput.value = 'AM';
                        ampmDisplay.innerHTML = `AM <i class="fa-solid fa-chevron-down caret-icon"></i>`;
                    }
                    if (wrapper.classList.contains('time-minute-wrapper') && ampmInput && !ampmInput.value) {
                        ampmInput.value = 'AM';
                        ampmDisplay.innerHTML = `AM <i class="fa-solid fa-chevron-down caret-icon"></i>`;
                    }
                }
            }
            if (onChange) {
                onChange();
            }
        });
    });

    return {
        getValue() {
            const is24h = (getTimeFormat() === '24h');
            const h = hourInput.value;
            const m = minuteInput.value;
            if (!h || !m) return '';
            
            if (is24h) {
                return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
            } else {
                const ap = ampmInput ? ampmInput.value : '';
                if (!ap) return '';
                let hour = parseInt(h, 10);
                if (ap === 'PM' && hour < 12) hour += 12;
                if (ap === 'AM' && hour === 12) hour = 0;
                return `${String(hour).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
            }
        },
        setValue24h(time24) {
            if (!time24) {
                setValue('', '', '');
                return;
            }
            const is24h = (getTimeFormat() === '24h');
            const [hStr, mStr] = time24.split(':');
            let hour = parseInt(hStr, 10);
            
            if (is24h) {
                setValue(String(hour).padStart(2, '0'), mStr, '');
            } else {
                let ampm = 'AM';
                if (hour >= 12) {
                    ampm = 'PM';
                    if (hour > 12) hour -= 12;
                }
                if (hour === 0) hour = 12;
                setValue(hour, mStr, ampm);
            }
        },
        refresh() {
            rebuildOptions();
            setValue('', '', '');
        }
    };
}

function toggleTaskDropdown(event, id) {
    event.stopPropagation();
    
    document.querySelectorAll('.task-dropdown.show').forEach(el => {
        if (el.id !== `dropdown-${id}`) {
            el.classList.remove('show');
            const oldCol = el.closest('.kanban-column');
            if (oldCol) oldCol.style.overflow = '';
        }
    });

    const dropdown = document.getElementById(`dropdown-${id}`);
    if (dropdown) {
        const column = dropdown.closest('.kanban-column');
        dropdown.classList.toggle('show');
        
        if (dropdown.classList.contains('show')) {
            if (column) column.style.overflow = 'visible';
            
            const rect = dropdown.getBoundingClientRect();
            const spaceBelow = window.innerHeight - rect.bottom;
            if (spaceBelow < 150) {
                dropdown.style.bottom = '100%';
                dropdown.style.top = 'auto';
                dropdown.style.marginTop = '0';
                dropdown.style.marginBottom = '5px';
            } else {
                dropdown.style.bottom = 'auto';
                dropdown.style.top = '100%';
                dropdown.style.marginTop = '5px';
                dropdown.style.marginBottom = '0';
            }
        } else {
            if (column) column.style.overflow = '';
        }
    }
}

window.toggleTaskDropdown = toggleTaskDropdown;

function initSettings() {
    const form = document.getElementById('settings-form');
    const passForm = document.getElementById('password-form');
    const nameInput = document.getElementById('settings-name');
    const emailInput = document.getElementById('settings-email');
    const clearBtn = document.getElementById('clear-data-btn');
    
    if (!form) return;
    
    const currentUser = JSON.parse(localStorage.getItem('currentUser'));
    
    if (currentUser) {
        nameInput.value = currentUser.name || '';
        emailInput.value = currentUser.email || '';
        emailInput.disabled = true;
        if (passForm) {
            passForm.style.opacity = '1';
            passForm.style.pointerEvents = 'auto';
            passForm.querySelectorAll('input, button').forEach(el => el.disabled = false);
        }
    } else {
        const guestName = localStorage.getItem('guestName') || 'Guest User';
        nameInput.value = guestName;
        emailInput.value = 'guest@local.device';
        emailInput.disabled = true;
        if (passForm) {
            passForm.style.opacity = '0.5';
            passForm.style.pointerEvents = 'none';
            passForm.querySelectorAll('input, button').forEach(el => el.disabled = true);
        }
    }

    if (settingsInitialized) return;
    settingsInitialized = true;

    const showTasksCb = document.getElementById('pref-show-tasks');
    const showEventsCb = document.getElementById('pref-show-events');
    const showHabitsCb = document.getElementById('pref-show-habits');

    if (showTasksCb && showEventsCb && showHabitsCb) {
        let prefs = JSON.parse(localStorage.getItem('calendarPreferences')) || {
            showTasks: true,
            showEvents: true,
            showHabits: true
        };

        showTasksCb.checked = prefs.showTasks;
        showEventsCb.checked = prefs.showEvents;
        showHabitsCb.checked = prefs.showHabits;

        [showTasksCb, showEventsCb, showHabitsCb].forEach(cb => {
            cb.addEventListener('change', () => {
                prefs.showTasks = showTasksCb.checked;
                prefs.showEvents = showEventsCb.checked;
                prefs.showHabits = showHabitsCb.checked;
                localStorage.setItem('calendarPreferences', JSON.stringify(prefs));

                if (window.calendarInstance) {
                    window.calendarInstance.refetchEvents();
                }
            });
        });

        const timeFormat = localStorage.getItem('timeFormat') || '12h';
        window.customTimeFormatSelect = initCustomSelect('pref-time-format-wrapper', (val) => {
            localStorage.setItem('timeFormat', val);
            if (window.timePickerStart) window.timePickerStart.refresh();
            if (window.timePickerEnd) window.timePickerEnd.refresh();
            if (window.timePickerDue) window.timePickerDue.refresh();
            displayTasks();
            if (window.calendarInstance) window.calendarInstance.refetchEvents();
        });
        window.customTimeFormatSelect.setValue(timeFormat, timeFormat === '24h' ? '24-Hour Format' : '12-Hour (AM/PM)');

        const dashboardLayout = localStorage.getItem('dashboardLayout') || 'list';
        window.customDashboardLayoutSelect = initCustomSelect('pref-dashboard-layout-wrapper', (val) => {
            localStorage.setItem('dashboardLayout', val);
            const listBtn = document.getElementById('view-list-btn');
            const kanbanBtn = document.getElementById('view-kanban-btn');
            if (listBtn && kanbanBtn) {
                if (val === 'kanban') {
                    listBtn.classList.remove('active');
                    kanbanBtn.classList.add('active');
                } else {
                    listBtn.classList.add('active');
                    kanbanBtn.classList.remove('active');
                }
            }
            displayTasks();
        });
        window.customDashboardLayoutSelect.setValue(dashboardLayout, dashboardLayout === 'kanban' ? 'Kanban Board' : 'Standard List');

        const currentTheme = localStorage.getItem('theme') || 'system';
        const themeCards = document.querySelectorAll('.theme-option-card');
        const themeInput = document.getElementById('pref-theme');

        function setThemeActiveCard(val) {
            themeCards.forEach(card => {
                if (card.getAttribute('data-value') === val) {
                    card.classList.add('selected');
                } else {
                    card.classList.remove('selected');
                }
            });
            if (themeInput) {
                themeInput.value = val;
                themeInput.dispatchEvent(new Event('change', { bubbles: true }));
            }
        }

        themeCards.forEach(card => {
            card.addEventListener('click', () => {
                const val = card.getAttribute('data-value');
                localStorage.setItem('theme', val);
                applyThemePreference(val);
                setThemeActiveCard(val);
            });
        });

        setThemeActiveCard(currentTheme);
    }

    form.addEventListener('submit', (e) => {
        e.preventDefault();
        const newName = nameInput.value.trim();
        const loggedUser = JSON.parse(localStorage.getItem('currentUser'));
        
        if (!loggedUser) {
            localStorage.setItem('guestName', newName);
            document.getElementById('display-username').textContent = newName;
            const dTitle = document.getElementById('dashboard-title');
            if (dTitle) dTitle.textContent = `Hello, ${newName}`;
            showToast('Guest profile updated successfully!', 'success', false);
            return;
        }

        // Use globals injected by the Firebase module script in index.html
        const user = auth ? auth.currentUser : null;
        if (!user) {
            showToast('You must be logged in!', 'error');
            return;
        }
        updateProfile(user, { displayName: newName })
            .then(() => {
                const cachedUser = JSON.parse(localStorage.getItem('currentUser')) || {};
                cachedUser.name = newName;
                localStorage.setItem('currentUser', JSON.stringify(cachedUser));
                document.getElementById('display-username').textContent = newName;
                const dTitle = document.getElementById('dashboard-title');
                if (dTitle) dTitle.textContent = `Hello, ${newName}`;
                showToast('Profile updated successfully!', 'success', false);
            })
            .catch((error) => {
                showToast(error.message, 'error');
            });
    });

    if (passForm) {
        passForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const currentPass = document.getElementById('current-password').value;
            const newPass = document.getElementById('new-password').value;

            // Use globals injected by the Firebase module script in index.html
            const user = auth ? auth.currentUser : null;
            if (!user) {
                showToast('You must be logged in!', 'error');
                return;
            }
            const credential = EmailAuthProvider.credential(user.email, currentPass);
            reauthenticateWithCredential(user, credential)
                .then(() => {
                    return updatePassword(user, newPass);
                })
                .then(() => {
                    passForm.reset();
                    showToast('Password updated securely!', 'success');
                })
                .catch((error) => {
                    console.error(error);
                    if (error.code === 'auth/invalid-credential') {
                        showToast('Current password incorrect!', 'error');
                    } else {
                        showToast(error.message, 'error');
                    }
                });
        });
    }

    if (clearBtn) {
        clearBtn.addEventListener('click', () => {
            showConfirm('This will permanently delete all your tasks, habits, and events. Are you sure?', () => {
                const currentUser = JSON.parse(localStorage.getItem('currentUser'));
                const currentUserId = currentUser ? currentUser.id : 'guest';
                getTasksFromFirebase().then(async (allItems) => {
                    const userTasks = allItems.filter(t => t.userId === currentUserId);
                    for (const task of userTasks) {
                        await deleteTaskFromFirebase(task.id);
                    }
                    localStorage.removeItem('firebase_tasks_cache');
                    const DB_NAME = 'ProductivityAppDB';
                    const req = indexedDB.deleteDatabase(DB_NAME);
                    req.onsuccess = () => {
                        setTimeout(() => window.location.reload(), 500);
                    };
                    req.onerror = () => {
                        setTimeout(() => window.location.reload(), 500);
                    };
                });
            });
        });
    }
}

function renderTempSubtasks() {
    const list = document.getElementById('subtasks-list');
    if (!list) return;
    list.innerHTML = '';
    tempSubtasks.forEach((sub, idx) => {
        list.innerHTML += `
            <li style="display:flex; justify-content:space-between; align-items:center; background: var(--item-bg); padding:8px 12px; border: 1px solid var(--border-color); border-radius:8px; font-size:13px;">
                <span style="${sub.completed ? 'text-decoration:line-through; opacity:0.6;' : ''}">${sub.title}</span>
                <i class="fa-solid fa-trash" style="cursor:pointer; color:#FF4D4F; padding:4px;" onclick="removeTempSubtask(${idx})"></i>
            </li>`;
    });
}

function removeTempSubtask(idx) {
    tempSubtasks.splice(idx, 1);
    renderTempSubtasks();
}

window.removeTempSubtask = removeTempSubtask;

let tempHabitTimers = [];

function renderHabitTimersList() {
    const listEl = document.getElementById('habit-timers-list');
    if (!listEl) return;
    if (tempHabitTimers.length === 0) {
        listEl.innerHTML = '<span style="font-size: 12.5px; color: var(--text-muted); font-style: italic;">No specific timers added. Uses Start Time if set.</span>';
        return;
    }
    listEl.innerHTML = tempHabitTimers.map((t, idx) => `
        <div class="habit-timer-chip">
            <i class="fa-regular fa-clock" style="font-size: 11px; color: var(--color-ticktick-blue);"></i>
            <span>${formatTaskTimeDisplay(t)}</span>
            <span class="habit-timer-chip-delete" onclick="removeHabitTimer(${idx})" title="Remove timer">
                <i class="fa-solid fa-xmark"></i>
            </span>
        </div>
    `).join('');
}

function removeHabitTimer(idx) {
    tempHabitTimers.splice(idx, 1);
    renderHabitTimersList();
}
window.removeHabitTimer = removeHabitTimer;

function initModalLogic() {
    const modal = document.getElementById('task-modal');
    const openBtns = document.querySelectorAll('.open-modal-btn');
    const closeBtn = document.getElementById('close-modal');
    const customFreqRow = document.getElementById('custom-freq-row');
    const specificDaysRow = document.getElementById('specific-days-row');
    const modalDelBtn = document.getElementById('modal-delete-btn');
    const addSubBtn = document.getElementById('add-subtask-btn');
    const subInput = document.getElementById('subtask-input');
    const habitAddTimerBtn = document.getElementById('habit-add-timer-btn');
    const habitTimerInput = document.getElementById('habit-new-timer-input');

    if (!modal) return;

    if (habitAddTimerBtn && habitTimerInput) {
        habitAddTimerBtn.addEventListener('click', () => {
            const val = habitTimerInput.value;
            if (val) {
                if (!tempHabitTimers.includes(val)) {
                    tempHabitTimers.push(val);
                    tempHabitTimers.sort();
                    renderHabitTimersList();
                }
                habitTimerInput.value = '';
            }
        });
        habitTimerInput.addEventListener('keypress', (e) => {
            if (e.key === 'Enter') {
                e.preventDefault();
                habitAddTimerBtn.click();
            }
        });
    }

    if (addSubBtn && subInput) {
        addSubBtn.addEventListener('click', () => {
            if (subInput.value.trim()) {
                tempSubtasks.push({ title: subInput.value.trim(), completed: false });
                subInput.value = '';
                renderTempSubtasks();
            }
        });
        subInput.addEventListener('keypress', (e) => {
            if (e.key === 'Enter') { e.preventDefault(); addSubBtn.click(); }
        });
    }

    // Task category filter bar chips
    const categoryChips = document.querySelectorAll('.btn-category-chip');
    categoryChips.forEach(chip => {
        chip.addEventListener('click', () => {
            categoryChips.forEach(c => c.classList.remove('active'));
            chip.classList.add('active');
            window.currentCategoryFilter = chip.getAttribute('data-category') || 'all';
            if (typeof window.sortAndRenderDashboard === 'function') {
                window.sortAndRenderDashboard();
            }
        });
    });

    openBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            const form = document.getElementById('task-form');
            if (form) form.reset();
            clearLiveDateErrors();
            document.getElementById('edit-item-id').value = ''; 
            document.getElementById('submit-btn').textContent = 'Save Details';
            if (modalDelBtn) modalDelBtn.style.display = 'none'; 
            if (customFreqRow) customFreqRow.style.display = 'none';
            if (specificDaysRow) specificDaysRow.style.display = 'none';
            
            document.getElementById('item-description').value = '';

            if (window.customPrioritySelect) {
                window.customPrioritySelect.setValue('medium', '<i class="fa-solid fa-flag" style="color: #FFA940;"></i> Medium');
            }
            if (window.customCategorySelect) {
                const meta = getCategoryMeta('Work');
                window.customCategorySelect.setValue('Work', `<i class="fa-solid ${meta.icon}" style="color:${meta.color};"></i> Work`);
            }
            if (window.customFrequencySelect) {
                window.customFrequencySelect.setValue('none', 'No Repeat');
            }
            if (window.customFreqUnitSelect) {
                window.customFreqUnitSelect.setValue('days', 'Days');
            }
            if (window.timePickerStart) {
                window.timePickerStart.setValue24h('');
            }
            if (window.timePickerEnd) {
                window.timePickerEnd.setValue24h('');
            }
            if (window.timePickerDue) {
                window.timePickerDue.setValue24h('');
            }

            document.querySelectorAll('.day-toggle input').forEach(cb => cb.checked = false);

            const defaultChoice = document.querySelector('input[name="event-end-choice"][value="date"]');
            if (defaultChoice) {
                defaultChoice.checked = true;
                defaultChoice.dispatchEvent(new Event('change'));
            }
            const durationNumInput = document.getElementById('event-duration-num');
            if (durationNumInput) durationNumInput.value = 60;
            if (window.customEventDurationUnitSelect) {
                window.customEventDurationUnitSelect.setValue('minutes', 'Minutes');
            }

            tempSubtasks = [];
            renderTempSubtasks();
            
            const type = btn.getAttribute('data-type'); 
            openModalUI(type);
        });
    });

    if (closeBtn) closeBtn.addEventListener('click', () => modal.classList.remove('active'));
    modal.addEventListener('click', (e) => {
        if (e.target === modal) {
            modal.classList.remove('active');
        }
    });

    if (modalDelBtn) {
        modalDelBtn.addEventListener('click', () => {
            const id = document.getElementById('edit-item-id').value;
            if (id) {
                showConfirm('Are you sure you want to delete this?', () => {
                    deleteTaskFromFirebase(id).then(() => {
                        showToast('Deleted successfully', 'success', false); 
                        modal.classList.remove('active');
                        displayTasks();
                        if (window.calendarInstance) window.calendarInstance.refetchEvents();
                    });
                });
            }
        });
    }

    const choiceRadios = document.querySelectorAll('input[name="event-end-choice"]');
    const endDateGroup = document.getElementById('event-end-date-group');
    const endTimeGroup = document.getElementById('event-end-time-group');
    const durationContainer = document.getElementById('event-duration-container');

    choiceRadios.forEach(radio => {
        radio.addEventListener('change', (e) => {
            const val = e.target.value;
            if (val === 'duration') {
                if (durationContainer) durationContainer.style.display = 'block';
                if (endDateGroup) endDateGroup.style.display = 'none';
                if (endTimeGroup) endTimeGroup.style.display = 'none';
            } else {
                if (durationContainer) durationContainer.style.display = 'none';
                if (endDateGroup) endDateGroup.style.display = 'block';
                if (endTimeGroup) endTimeGroup.style.display = 'block';
            }
        });
    });

    initFormSubmit(modal);
}

function openModalUI(type) {
    const modal = document.getElementById('task-modal');
    const modalTitle = document.getElementById('modal-title');
    const itemTypeInput = document.getElementById('item-type');
    const startDateRow = document.getElementById('start-date-row');
    const taskDetailsRow = document.getElementById('task-details-row');
    const deadlineContainer = document.getElementById('deadline-container');
    const eventOnlyElements = document.querySelectorAll('.id-event-only');
    const taskOnlyElements = document.querySelectorAll('.id-task-only');
    const labelTimeStart = document.getElementById('label-time-start');

    if (!modal) return;
    itemTypeInput.value = type;
    
    if (!document.getElementById('task-start-date').value) {
        document.getElementById('task-start-date').value = new Date().toISOString().split('T')[0];
    }

    if (type === 'task') {
        modalTitle.innerHTML = '<i class="fa-solid fa-list-check"></i> Task Details';
        labelTimeStart.textContent = 'Time (Optional)';
        startDateRow.style.display = 'flex';
        taskDetailsRow.style.display = 'flex';
        deadlineContainer.style.display = 'block';
        eventOnlyElements.forEach(el => el.style.display = 'none');
        taskOnlyElements.forEach(el => el.style.display = 'block');
    } else if (type === 'event') {
        modalTitle.innerHTML = '<i class="fa-solid fa-calendar-plus"></i> Event Details';
        labelTimeStart.textContent = 'Start Time';
        startDateRow.style.display = 'flex';
        taskDetailsRow.style.display = 'flex'; 
        deadlineContainer.style.display = 'none';
        
        const choiceContainer = document.getElementById('event-end-choice-container');
        if (choiceContainer) choiceContainer.style.display = 'block';
        
        const currentChoice = document.querySelector('input[name="event-end-choice"]:checked').value;
        const endDateGroup = document.getElementById('event-end-date-group');
        const endTimeGroup = document.getElementById('event-end-time-group');
        const durationContainer = document.getElementById('event-duration-container');
        
        if (currentChoice === 'duration') {
            if (durationContainer) durationContainer.style.display = 'block';
            if (endDateGroup) endDateGroup.style.display = 'none';
            if (endTimeGroup) endTimeGroup.style.display = 'none';
        } else {
            if (durationContainer) durationContainer.style.display = 'none';
            if (endDateGroup) endDateGroup.style.display = 'block';
            if (endTimeGroup) endTimeGroup.style.display = 'block';
        }
        
        taskOnlyElements.forEach(el => el.style.display = 'none');
        
        if (!document.getElementById('event-end-date').value) {
            document.getElementById('event-end-date').value = new Date().toISOString().split('T')[0];
        }
    } else if (type === 'habit') {
        modalTitle.innerHTML = '<i class="fa-solid fa-rotate"></i> Habit Details';
        startDateRow.style.display = 'flex'; 
        labelTimeStart.textContent = 'Time (Optional)';
        taskDetailsRow.style.display = 'flex';
        deadlineContainer.style.display = 'none';
        eventOnlyElements.forEach(el => el.style.display = 'none');
        taskOnlyElements.forEach(el => el.style.display = 'none');
        
        const habitOnlyElements = document.querySelectorAll('.id-habit-only');
        habitOnlyElements.forEach(el => el.style.display = 'block');

        if (window.customFrequencySelect && window.customFrequencySelect.getValue() === 'none') {
            window.customFrequencySelect.setValue('daily', 'Daily');
        }
    } else {
        const habitOnlyElements = document.querySelectorAll('.id-habit-only');
        habitOnlyElements.forEach(el => el.style.display = 'none');
    }
    modal.classList.add('active');
}

function editItem(id) {
    getTasksFromFirebase().then(tasks => {
        const item = tasks.find(t => String(t.id) === String(id));
        if (!item) return;

        const form = document.getElementById('task-form');
        if (form) form.reset();
        clearLiveDateErrors();
        document.getElementById('edit-item-id').value = item.id;
        document.getElementById('submit-btn').textContent = 'Update Details';
        document.getElementById('modal-delete-btn').style.display = 'block'; 

        document.getElementById('task-title').value = item.title;
        document.getElementById('task-start-date').value = item.startDate;
        
        document.getElementById('item-description').value = item.description || '';
        
        if (window.timePickerStart) {
            window.timePickerStart.setValue24h(item.startTime || '');
        }
        
        if (window.customFrequencySelect) {
            let label = 'No Repeat';
            let freqValue = item.frequency || 'none';
            if (freqValue === 'specific_days') {
                freqValue = 'custom';
                item.frequency = 'custom';
                item.customUnit = 'weeks';
            }
            
            if (freqValue === 'daily') label = 'Daily';
            else if (freqValue === 'weekly') label = 'Weekly';
            else if (freqValue === 'monthly') label = 'Monthly';
            else if (freqValue === 'yearly') label = 'Yearly';
            else if (freqValue === 'custom') label = 'Custom';
            window.customFrequencySelect.setValue(freqValue, label);
        }

        document.getElementById('custom-freq-row').style.display = 'none';
        document.getElementById('specific-days-row').style.display = 'none';

        if (item.frequency === 'custom') {
            document.getElementById('custom-freq-row').style.display = 'block';
            document.getElementById('custom-freq-num').value = item.customNum || 1;
            
            const unit = item.customUnit || 'days';
            if (window.customFreqUnitSelect) {
                const uLabel = unit.charAt(0).toUpperCase() + unit.slice(1);
                window.customFreqUnitSelect.setValue(unit, uLabel);
            }
            
            if (unit === 'weeks') {
                document.getElementById('specific-days-row').style.display = 'block';
                const boxes = document.querySelectorAll('.day-toggle input');
                boxes.forEach(cb => {
                    cb.checked = item.specificDays && item.specificDays.includes(parseInt(cb.value, 10));
                });
            }
            document.getElementById('times-per-day').value = item.timesPerDay || 1;
        } else {
            document.getElementById('times-per-day').value = item.timesPerDay || 1;
        }

        if (item.type === 'habit') {
            tempHabitTimers = Array.isArray(item.reminderTimes) && item.reminderTimes.length > 0
                ? [...item.reminderTimes]
                : (item.startTime ? [item.startTime] : []);
            renderHabitTimersList();
            const habitTimesInput = document.getElementById('habit-times-per-day');
            if (habitTimesInput) habitTimesInput.value = item.timesPerDay || 1;
        }

        if (item.type === 'task') {
            const cat = item.category || 'Work';
            const catInput = document.getElementById('task-category');
            if (catInput) catInput.value = cat;
            if (window.customCategorySelect) {
                const meta = getCategoryMeta(cat);
                window.customCategorySelect.setValue(cat, `<i class="fa-solid ${meta.icon}" style="color:${meta.color};"></i> ${meta.name}`);
            }

            if (item.dueDate) document.getElementById('task-due-date').value = item.dueDate;
            if (window.timePickerDue) {
                window.timePickerDue.setValue24h(item.dueTime || '');
            }
            
            if (window.customPrioritySelect) {
                const prio = item.priority || 'medium';
                let prioHTML = '<i class="fa-solid fa-flag" style="color: #FFA940;"></i> Medium';
                if (prio === 'high') prioHTML = '<i class="fa-solid fa-flag" style="color: #FF4D4F;"></i> High';
                else if (prio === 'low') prioHTML = '<i class="fa-solid fa-flag" style="color: #2F7BF6;"></i> Low';
                window.customPrioritySelect.setValue(prio, prioHTML);
            }

            tempSubtasks = item.subtasks ? [...item.subtasks] : [];
            renderTempSubtasks();
        } else if (item.type === 'event') {
            document.getElementById('event-end-date').value = item.endDate;
            if (window.timePickerEnd) {
                window.timePickerEnd.setValue24h(item.endTime || '');
            }
        }

        const detailsModal = document.getElementById('details-modal');
        if (detailsModal) detailsModal.classList.remove('active');

        openModalUI(item.type);
    });
}

window.editItem = editItem;

function initFormSubmit(modal) {
    const form = document.getElementById('task-form');
    if (!form) return;
    // Guard: only attach the submit listener once even if initFormSubmit is called again.
    if (form.dataset.listenerAttached) return;
    form.dataset.listenerAttached = 'true';

    form.addEventListener('submit', (e) => {
        e.preventDefault();

        const submitBtn = document.getElementById('submit-btn');
        if (submitBtn.disabled) return;
        
        submitBtn.disabled = true;
        const originalBtnText = submitBtn.textContent;
        submitBtn.textContent = 'Saving...';

        if (window.timePickerStart) {
            document.getElementById('task-start-time').value = window.timePickerStart.getValue();
        }
        if (window.timePickerEnd) {
            document.getElementById('event-end-time').value = window.timePickerEnd.getValue();
        }
        if (window.timePickerDue) {
            document.getElementById('task-due-time').value = window.timePickerDue.getValue();
        }

        const editId = document.getElementById('edit-item-id').value;
        const type = document.getElementById('item-type').value;
        const title = document.getElementById('task-title').value;
        const startDate = document.getElementById('task-start-date').value;
        const startTime = document.getElementById('task-start-time').value;
        
        const frequency = window.customFrequencySelect ? window.customFrequencySelect.getValue() : 'none';
        const currentUser = JSON.parse(localStorage.getItem('currentUser'));
        const userId = currentUser ? currentUser.id : 'guest';

        let dataItem = {
            userId: userId,
            type: type,
            title: title,
            startDate: startDate,
            startTime: startTime || null,
            frequency: frequency,
            isCompleted: false,
            isCancelled: false, 
            completedCount: 0,
            description: document.getElementById('item-description').value.trim() || null
        };

        dataItem.timesPerDay = parseInt(document.getElementById('times-per-day').value, 10) || 1;
        
        if (frequency === 'custom') {
            dataItem.customNum = parseInt(document.getElementById('custom-freq-num').value, 10) || 1;
            dataItem.customUnit = window.customFreqUnitSelect ? window.customFreqUnitSelect.getValue() : 'days';
            
            if (dataItem.customUnit === 'weeks') {
                const selectedDays = Array.from(document.querySelectorAll('.day-toggle input:checked')).map(cb => parseInt(cb.value, 10));
                if (selectedDays.length === 0) {
                    const startDay = new Date(startDate).getDay();
                    dataItem.specificDays = [startDay];
                } else {
                    dataItem.specificDays = selectedDays;
                }
            } else {
                dataItem.specificDays = null;
            }
        } else {
            dataItem.specificDays = null;
        }

        if (type === 'task') {
            const dueDate = document.getElementById('task-due-date').value;
            const dueTime = document.getElementById('task-due-time').value;
            if (dueDate) {
                const startDateTime = new Date(`${startDate}T${startTime || '00:00'}`);
                const dueDateTime = new Date(`${dueDate}T${dueTime || '23:59'}`);
                if (dueDateTime < startDateTime) {
                    showToast('Deadline cannot be before start time!', 'error');
                    submitBtn.disabled = false;
                    submitBtn.textContent = originalBtnText;
                    return;
                }
            }
            dataItem.dueDate = dueDate || null;
            dataItem.dueTime = dueTime || null;
            dataItem.priority = window.customPrioritySelect ? window.customPrioritySelect.getValue() : 'medium';
            dataItem.category = window.customCategorySelect ? window.customCategorySelect.getValue() : (document.getElementById('task-category')?.value || 'Work');
            dataItem.subtasks = [...tempSubtasks]; 
        } else if (type === 'event') {
            const eventEndChoice = document.querySelector('input[name="event-end-choice"]:checked').value;
            let endDate = '';
            let endTime = null;

            if (eventEndChoice === 'duration') {
                const durationNum = parseInt(document.getElementById('event-duration-num').value, 10) || 60;
                const durationUnit = document.getElementById('event-duration-unit').value || 'minutes';
                
                const startDateTimeStr = `${startDate}T${startTime || '00:00'}`;
                const startDateTime = new Date(startDateTimeStr);
                const endDateTime = new Date(startDateTime.getTime());
                
                if (durationUnit === 'minutes') {
                    endDateTime.setMinutes(endDateTime.getMinutes() + durationNum);
                } else if (durationUnit === 'hours') {
                    endDateTime.setHours(endDateTime.getHours() + durationNum);
                } else if (durationUnit === 'days') {
                    endDateTime.setDate(endDateTime.getDate() + durationNum);
                } else if (durationUnit === 'weeks') {
                    endDateTime.setDate(endDateTime.getDate() + (durationNum * 7));
                } else if (durationUnit === 'months') {
                    endDateTime.setMonth(endDateTime.getMonth() + durationNum);
                } else if (durationUnit === 'years') {
                    endDateTime.setFullYear(endDateTime.getFullYear() + durationNum);
                }
                
                const ey = endDateTime.getFullYear();
                const em = String(endDateTime.getMonth() + 1).padStart(2, '0');
                const ed = String(endDateTime.getDate()).padStart(2, '0');
                endDate = `${ey}-${em}-${ed}`;
                
                const eh = String(endDateTime.getHours()).padStart(2, '0');
                const emin = String(endDateTime.getMinutes()).padStart(2, '0');
                endTime = `${eh}:${emin}`;
            } else {
                endDate = document.getElementById('event-end-date').value;
                endTime = document.getElementById('event-end-time').value;
                
                const startFull = new Date(`${startDate}T${startTime || '00:00'}`);
                const endFull = new Date(`${endDate}T${endTime || '00:00'}`);
                if (startFull > endFull) {
                    showToast('End time cannot be before start time!', 'error');
                    submitBtn.disabled = false;
                    submitBtn.textContent = originalBtnText;
                    return;
                }
            }
            dataItem.endDate = endDate;
            dataItem.endTime = endTime || null;
            dataItem.priority = 'medium'; 
        } else if (type === 'habit') {
            dataItem.priority = 'medium';
            const habitTimesVal = parseInt(document.getElementById('habit-times-per-day').value, 10) || 1;
            dataItem.timesPerDay = Math.max(1, habitTimesVal);
            dataItem.reminderTimes = [...tempHabitTimers];
            if (tempHabitTimers.length > 0) {
                dataItem.startTime = tempHabitTimers[0];
            }
        }

        getTasksFromFirebase().then(allItems => {
            const originalItem = allItems.find(t => String(t.id) === String(editId));
            if (originalItem) {
                if (originalItem.completedDates) {
                    dataItem.completedDates = originalItem.completedDates;
                }
                if (originalItem.dailyProgress) {
                    dataItem.dailyProgress = originalItem.dailyProgress;
                }
                if (originalItem.createdAt) {
                    dataItem.createdAt = originalItem.createdAt;
                }
            } else {
                if (type === 'habit') {
                    dataItem.completedDates = [];
                }
            }

            if (editId) {
                dataItem.id = editId;
            } else {
                dataItem.createdAt = new Date().getTime();
            }

            saveTaskToFirebase(dataItem).then(() => {
                if (window.scheduleItemNotifications) {
                    window.scheduleItemNotifications(dataItem);
                }
                finishSubmit(editId ? 'Updated successfully!' : 'Saved successfully!', false);
            }).catch(e => {
                console.error(e);
                submitBtn.disabled = false;
                submitBtn.textContent = originalBtnText;
                showToast('Failed to save task: ' + e.message, 'error');
            });
        });

        function finishSubmit(msg, playAudioFlag) {
            form.reset();
            document.getElementById('edit-item-id').value = '';
            modal.classList.remove('active');
            showToast(msg, 'success', playAudioFlag);
            displayTasks();
            if (window.calendarInstance) window.calendarInstance.refetchEvents();
            
            submitBtn.disabled = false;
            submitBtn.textContent = 'Save Details';
        }
    });
}

function clearLiveDateErrors() {
    const dueDateInput = document.getElementById('task-due-date');
    if (dueDateInput) {
        dueDateInput.style.border = '';
        dueDateInput.style.boxShadow = '';
        const err = dueDateInput.parentElement.querySelector('.live-date-error');
        if (err) err.remove();
    }
}

function isHabitScheduledOnDay(item, dateObj) {
    if (item.type !== 'habit') return false;
    const freq = item.frequency;
    if (freq === 'daily') return true;
    if (freq === 'custom') {
        const unit = item.customUnit;
        if (unit === 'days') {
            const start = new Date(item.startDate);
            start.setHours(0,0,0,0);
            const target = new Date(dateObj);
            target.setHours(0,0,0,0);
            const diffTime = target - start;
            if (diffTime < 0) return false;
            const diffDays = Math.round(diffTime / (1000 * 60 * 60 * 24));
            return (diffDays % (item.customNum || 1)) === 0;
        }
        if (unit === 'weeks') {
            const dayOfWeek = dateObj.getDay();
            if (item.specificDays && item.specificDays.includes(dayOfWeek)) {
                const start = new Date(item.startDate);
                start.setHours(0,0,0,0);
                const target = new Date(dateObj);
                target.setHours(0,0,0,0);
                
                const startSun = new Date(start);
                startSun.setDate(start.getDate() - start.getDay());
                const targetSun = new Date(target);
                targetSun.setDate(target.getDate() - target.getDay());
                
                const diffTime = targetSun - startSun;
                if (diffTime < 0) return false;
                const diffWeeks = Math.round(diffTime / (1000 * 60 * 60 * 24 * 7));
                return (diffWeeks % (item.customNum || 1)) === 0;
            }
            return false;
        }
        if (unit === 'months') {
            const start = new Date(item.startDate);
            const target = new Date(dateObj);
            if (target < start) return false;
            if (target.getDate() !== start.getDate()) return false;
            
            const diffMonths = (target.getFullYear() - start.getFullYear()) * 12 + (target.getMonth() - start.getMonth());
            return (diffMonths % (item.customNum || 1)) === 0;
        }
    }
    
    if (freq === 'weekly') {
        const start = new Date(item.startDate);
        return dateObj.getDay() === start.getDay();
    }
    if (freq === 'monthly') {
        const start = new Date(item.startDate);
        return dateObj.getDate() === start.getDate();
    }
    if (freq === 'yearly') {
        const start = new Date(item.startDate);
        return dateObj.getDate() === start.getDate() && dateObj.getMonth() === start.getMonth();
    }
    
    return true;
}

window._habitCalendarOffset = window._habitCalendarOffset || new Map();
function shiftHabitCalendar(itemId, delta) {
    const current = window._habitCalendarOffset.get(itemId) || 0;
    window._habitCalendarOffset.set(itemId, current + delta);
    displayTasks();
}

window.shiftHabitCalendar = shiftHabitCalendar;

function renderTaskCard(item, { isHistory = false, showHabitCalendar = true, showSubtasks = true } = {}) {
    let typeBadgeHTML = '';
    if (isHistory) {
        const itemType = item.type || 'task';
        let icon = 'fa-check-double';
        if (itemType === 'event') icon = 'fa-calendar-day';
        else if (itemType === 'habit') icon = 'fa-repeat';
        typeBadgeHTML = `<span class="history-type-badge ${itemType}"><i class="fa-solid ${icon}"></i> ${itemType}</span>`;
    }

    let timeInfo = item.startTime ? ` <i class="fa-regular fa-clock"></i> ${formatTaskTimeDisplay(item.startTime)}` : '';
    if (item.type === 'habit' && item.reminderTimes && item.reminderTimes.length > 0) {
        timeInfo = ` <i class="fa-regular fa-bell"></i> ${item.reminderTimes.map(t => formatTaskTimeDisplay(t)).join(', ')}`;
    }
    let freqText = '';
    
    if (item.frequency && item.frequency !== 'none') {
        if (item.frequency === 'custom') freqText = ` (Every ${item.customNum} ${item.customUnit})`;
        else if (item.frequency === 'specific_days') freqText = ` (Custom Days)`;
        else { const dict = { 'daily':'Daily', 'weekly':'Weekly', 'monthly':'Monthly', 'yearly':'Yearly' }; freqText = ` (${dict[item.frequency]})`; }
    }
    
    let progressBadge = '';
    if (item.timesPerDay > 1 && !item.isCancelled && !item.isDeleted) {
        let count = item.completedCount || 0;
        if (item.isCompleted) count = item.timesPerDay;
        progressBadge = `<span class="progress-badge ${item.isCompleted ? 'completed' : ''}">${count}/${item.timesPerDay}</span>`;
    }

    if (item.isCancelled) {
        progressBadge = `<span class="badge-cancelled">Won't Do</span>`;
    } else if (item.isCompleted && isHistory) {
        progressBadge = `<span class="badge-completed">Completed</span>`;
    } else if (item.isDeleted) {
        progressBadge = `<span class="badge-deleted">Deleted</span>`;
    }

    let flagIcon = '';
    let categoryBadgeHTML = '';
    if (item.type === 'task' || !item.type) {
        const cat = item.category || 'Work';
        const catMeta = getCategoryMeta(cat);
        categoryBadgeHTML = `<span class="task-category-pill" style="border: 1px solid ${catMeta.color}35; background:${catMeta.bg}; color:${catMeta.color};"><i class="fa-solid ${catMeta.icon}"></i> ${catMeta.name}</span>`;
    }
    if (item.type === 'task') {
        if (item.priority === 'high') flagIcon = ' <i class="fa-solid fa-flag" style="color: #FF4D4F; font-size: 13px;"></i>';
        else if (item.priority === 'medium') flagIcon = ' <i class="fa-solid fa-flag" style="color: #FFA940; font-size: 13px;"></i>';
        else if (item.priority === 'low') flagIcon = ' <i class="fa-solid fa-flag" style="color: #2F7BF6; font-size: 13px;"></i>';
    }

    const itemClass = item.isCancelled ? 'cancelled' : (item.isCompleted ? 'completed' : '');

    let habitCalendarHTML = '';
    if (item.type === 'habit' && showHabitCalendar && !isHistory) {
        const monthNames = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
        const offset = (window._habitCalendarOffset && window._habitCalendarOffset.get(item.id)) || 0;
        
        const curDate = new Date();
        const targetDate = new Date(curDate.getFullYear(), curDate.getMonth() + offset, 1);
        const curYear = targetDate.getFullYear();
        const curMonth = targetDate.getMonth();
        const daysInMonth = new Date(curYear, curMonth + 1, 0).getDate();
        const monthTitle = `${monthNames[curMonth]} ${curYear}`;
        
        const firstDayIndex = new Date(curYear, curMonth, 1).getDay(); 
        
        const cDate = new Date(item.createdAt || Date.now());
        const cYear = cDate.getFullYear();
        const cMonth = cDate.getMonth();
        const cDay = cDate.getDate();
        
        let gridHTML = '';
        
        const dayInitials = ['Su', 'Mo', 'Tu', 'We', 'Th', 'Fr', 'Sa'];
        dayInitials.forEach(initial => {
            gridHTML += `<div class="day-initial">${initial}</div>`;
        });
        
        const renderDayHelper = (y, m, d, isOtherMonth) => {
            const dayDateStr = `${y}-${String(m + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
            let dayClass = 'day-circle';
            if (isOtherMonth) dayClass += ' other-month';
            let dayContent = `${d}`;

            const dDate = new Date(y, m, d);
            const isBeforeCreation = (y < cYear) || 
                                     (y === cYear && m < cMonth) || 
                                     (y === cYear && m === cMonth && d < cDay);
                                     
            const isFuture = (y > curDate.getFullYear()) ||
                             (y === curDate.getFullYear() && m > curDate.getMonth()) ||
                             (y === curDate.getFullYear() && m === curDate.getMonth() && d > curDate.getDate());
                             
            const isScheduled = isHabitScheduledOnDay(item, dDate);
            const isToday = y === curDate.getFullYear() && m === curDate.getMonth() && d === curDate.getDate();

            if (isBeforeCreation) {
                dayClass += ' untouched';
            } else if (isFuture) {
                dayClass += ' future';
                if (isScheduled) {
                    dayClass += ' scheduled';
                }
            } else {
                const isChecked = item.completedDates && item.completedDates.includes(dayDateStr);
                const isSkipped = item.skippedDates && item.skippedDates.includes(dayDateStr);
                const dayProgress = (item.dailyProgress && item.dailyProgress[dayDateStr]) || 0;
                const target = item.timesPerDay || 1;

                if (isChecked || (dayProgress >= target && target > 0)) {
                    dayClass += ' checked';
                    dayContent = '<i class="fa-solid fa-check"></i>';
                } else if (isSkipped) {
                    dayClass += ' skipped';
                    dayContent = '<i class="fa-solid fa-ban"></i>';
                } else if (isToday && isScheduled) {
                    dayClass += ' today-scheduled';
                    dayContent = target > 1 && dayProgress > 0 ? `${dayProgress}/${target}` : `${d}`;
                } else {
                    dayClass += ' unchecked';
                    dayContent = '<i class="fa-solid fa-xmark"></i>';
                }
            }

            const clickAttr = (!isBeforeCreation && !isFuture) ? `onclick="toggleHabitDay(event, '${item.id}', '${dayDateStr}')"` : '';
            return `<div class="${dayClass}" title="${dayDateStr}" ${clickAttr}>${dayContent}</div>`;
        };

        // 1. Previous month days
        const prevMonthDate = new Date(curYear, curMonth, 0);
        const prevMonthYear = prevMonthDate.getFullYear();
        const prevMonth = prevMonthDate.getMonth();
        const daysInPrevMonth = prevMonthDate.getDate();

        for (let s = firstDayIndex - 1; s >= 0; s--) {
            const prevD = daysInPrevMonth - s;
            gridHTML += renderDayHelper(prevMonthYear, prevMonth, prevD, true);
        }

        // 2. Current month days
        for (let d = 1; d <= daysInMonth; d++) {
            gridHTML += renderDayHelper(curYear, curMonth, d, false);
        }

        // 3. Next month days
        const nextMonthDate = new Date(curYear, curMonth + 1, 1);
        const nextMonthYear = nextMonthDate.getFullYear();
        const nextMonth = nextMonthDate.getMonth();
        const remainingCells = 42 - (firstDayIndex + daysInMonth);
        for (let nextD = 1; nextD <= remainingCells; nextD++) {
            gridHTML += renderDayHelper(nextMonthYear, nextMonth, nextD, true);
        }
        
        const minOffset = (cYear - curDate.getFullYear()) * 12 + (cMonth - curDate.getMonth());
        const maxOffset = 1;
        const prevDisabled = offset <= minOffset ? 'disabled style="opacity: 0.3; cursor: not-allowed;"' : '';
        const nextDisabled = offset >= maxOffset ? 'disabled style="opacity: 0.3; cursor: not-allowed;"' : '';

        habitCalendarHTML = `
            <div class="habit-calendar-wrapper" onclick="event.stopPropagation();">
                <div class="habit-calendar-header" style="display: flex; justify-content: space-between; align-items: center; gap: 8px;">
                    <div style="display: flex; align-items: center; gap: 4px;">
                        <button class="habit-nav-btn" onclick="shiftHabitCalendar('${item.id}', -1)" ${prevDisabled} style="background: none; border: none; color: var(--text-muted); cursor: pointer; font-size: 14px; padding: 2px 6px; border-radius: 4px; display: flex; align-items: center; justify-content: center;"><i class="fa-solid fa-chevron-left"></i></button>
                        <span class="habit-calendar-title" style="font-weight: 600; min-width: 100px; text-align: center; color: var(--text-main); font-size: 14px;">${monthTitle}</span>
                        <button class="habit-nav-btn" onclick="shiftHabitCalendar('${item.id}', 1)" ${nextDisabled} style="background: none; border: none; color: var(--text-muted); cursor: pointer; font-size: 14px; padding: 2px 6px; border-radius: 4px; display: flex; align-items: center; justify-content: center;"><i class="fa-solid fa-chevron-right"></i></button>
                    </div>
                    <div class="habit-calendar-legend" style="margin-left: auto;">
                        <div class="legend-item"><span class="legend-dot checked"></span> Done</div>
                        <div class="legend-item"><span class="legend-dot skipped"></span> Skipped</div>
                        <div class="legend-item"><span class="legend-dot unchecked"></span> Missed</div>
                    </div>
                </div>
                <div class="habit-calendar-grid">
                    ${gridHTML}
                </div>
            </div>
        `;
    }

    let subtasksHTML = '';
    if (item.subtasks && item.subtasks.length > 0 && showSubtasks && !isHistory) {
        subtasksHTML = '<div class="subtasks-wrapper">';
        item.subtasks.forEach((sub, idx) => {
            subtasksHTML += `
                <div class="subtask-item ${sub.completed ? 'completed' : ''}">
                    <input type="checkbox" class="subtask-checkbox" ${sub.completed ? 'checked' : ''} onchange="toggleSubtask('${item.id}', ${idx}, ${sub.completed})">
                    <span class="subtask-text">${sub.title}</span>
                </div>
            `;
        });
        subtasksHTML += '</div>';
    }

    let actionButtons = '';
    let dropdownItems = '';

    if (isHistory) {
        actionButtons = `
            <button onclick="restoreItem('${item.id}')" class="btn-icon btn-edit" title="Restore"><i class="fa-solid fa-rotate-left"></i></button>
            <button onclick="deleteItem('${item.id}')" class="btn-icon btn-delete" title="Delete"><i class="fa-solid fa-trash"></i></button>
        `;
        dropdownItems = `
            <button class="dropdown-item" onclick="restoreItem('${item.id}')"><i class="fa-solid fa-rotate-left"></i> Restore</button>
            <button class="dropdown-item danger" onclick="deleteItem('${item.id}')"><i class="fa-solid fa-trash"></i> Delete</button>
        `;
    } else {
        let cancelBtnDesktop = (!item.isCompleted && !item.isCancelled && item.type !== 'habit') ? `<button onclick="cancelItem('${item.id}')" class="btn-icon btn-cancel" title="Mark as Won't Do"><i class="fa-solid fa-ban"></i></button>` : '';
        let cancelBtnMobile = (!item.isCompleted && !item.isCancelled && item.type !== 'habit') ? `<button class="dropdown-item" onclick="cancelItem('${item.id}')"><i class="fa-solid fa-ban"></i> Won't Do</button>` : '';
        
        actionButtons = `
            <button onclick="editItem('${item.id}')" class="btn-icon btn-edit" title="Edit"><i class="fa-solid fa-pen"></i></button>
            ${cancelBtnDesktop}
            <button onclick="deleteItem('${item.id}')" class="btn-icon btn-delete" title="Delete"><i class="fa-solid fa-trash"></i></button>
        `;
        dropdownItems = `
            <button class="dropdown-item" onclick="editItem('${item.id}')"><i class="fa-solid fa-pen"></i> Edit</button>
            ${cancelBtnMobile}
            <button class="dropdown-item danger" onclick="deleteItem('${item.id}')"><i class="fa-solid fa-trash"></i> Delete</button>
        `;
    }

    let checkboxHTML = isHistory ? '' : `<input type="checkbox" class="custom-checkbox" ${item.isCompleted ? 'checked' : ''} ${item.isCancelled ? 'disabled' : ''} onchange="toggleItemComplete('${item.id}', ${item.isCompleted})">`;

    let dueInfo = '';
    if (item.dueDate) {
        dueInfo = ` <span style="font-size:11px; color:#FF4D4F; margin-left: 8px; font-weight: 500;"><i class="fa-regular fa-calendar-xmark"></i> Due: ${item.dueDate}${item.dueTime ? ' ' + formatTaskTimeDisplay(item.dueTime) : ''}</span>`;
    }

    const isSwipeable = !isHistory && !item.isCompleted && !item.isCancelled && !item.isDeleted;
    const canCancel = isSwipeable && item.type !== 'habit';

    return `
        <div class="task-wrapper type-${item.type}" data-task-id="${item.id}" onclick="showItemDetails('${item.id}')">
            <div class="task-swipe-wrapper ${isSwipeable ? 'swipeable-task' : ''}" data-task-id="${item.id}" data-can-cancel="${canCancel ? 'true' : 'false'}">
                ${isSwipeable ? `
                <div class="task-swipe-track">
                    <div class="task-swipe-action task-swipe-action-done"><i class="fa-solid fa-check"></i> <span>Done</span></div>
                    ${canCancel ? `<div class="task-swipe-action task-swipe-action-wontdo"><span>Won't Do</span> <i class="fa-solid fa-ban"></i></div>` : `<div class="task-swipe-action"></div>`}
                </div>` : ''}
                <div class="task-item ${itemClass}" style="border-left-color: ${getColor(item.priority)}; border-left-width: 0;">
                    <div class="task-info-simple">
                        <span onclick="event.stopPropagation();">${checkboxHTML}</span>
                        <h4 class="task-item-title">
                            ${typeBadgeHTML}${item.title} ${categoryBadgeHTML} ${flagIcon} ${progressBadge}
                            <span style="font-size:12px; color:var(--text-muted); font-weight:normal;">${timeInfo} ${freqText}</span>
                            ${dueInfo}
                        </h4>
                    </div>
                    <div class="task-actions" onclick="event.stopPropagation();">
                        <div class="task-actions-desktop">${actionButtons}</div>
                        <div class="task-menu-container">
                            <button class="btn-menu" onclick="toggleTaskDropdown(event, '${item.id}')"><i class="fa-solid fa-ellipsis-vertical"></i></button>
                            <div class="task-dropdown" id="dropdown-${item.id}">
                                ${dropdownItems}
                            </div>
                        </div>
                    </div>
                </div>
            </div>
            ${subtasksHTML ? `<span onclick="event.stopPropagation();">${subtasksHTML}</span>` : ''}
            ${habitCalendarHTML || ''}
        </div>
    `;
}

function displayTasks() {
    const habitsContainer = document.getElementById('habits-container');
    const historyContainer = document.getElementById('history-tasks');
    const pomodoroSelect = document.getElementById('pomodoro-task-select');
    const pomodoroBtn = document.getElementById('pomodoro-mark-done');

    const currentUser = JSON.parse(localStorage.getItem('currentUser'));
    const currentUserId = currentUser ? currentUser.id : 'guest';

    getTasksFromFirebase().then(allItems => {
        const items = allItems.filter(item => item.userId === currentUserId);
        window.allUserItemsList = items; 
        
        if (habitsContainer) habitsContainer.innerHTML = '';
        if (historyContainer) historyContainer.innerHTML = '';

        const todayStr = getTodayStr();
        const now = new Date();
        const currentDayOfWeek = now.getDay();
        const nowMs = Date.now();

        const tasks = items.filter(i => (i.type === 'task' || !i.type) && !i.isDeleted);
        const habits = items.filter(i => i.type === 'habit' && !i.isDeleted);

        window.activeTasksList = tasks.filter(t => !t.isCompleted && !t.isCancelled).sort((a, b) => b.createdAt - a.createdAt);
        window.allActiveItemsList = items.filter(t => (!t.isCompleted || t.type === 'habit' || (t.frequency && t.frequency !== 'none')) && !t.isCancelled && !t.isDeleted);
        
        window.allActiveItemsList = items.filter(t => (!t.isCompleted || t.type === 'habit' || (t.frequency && t.frequency !== 'none')) && !t.isCancelled && !t.isDeleted);

        habits.forEach(h => {
            const target = h.timesPerDay || 1;
            if (!h.dailyProgress) h.dailyProgress = {};
            if (h.completedDates && h.completedDates.includes(todayStr) && (h.dailyProgress[todayStr] === undefined)) {
                h.dailyProgress[todayStr] = target;
            }
            const todayCount = h.dailyProgress[todayStr] || 0;
            h.completedCount = todayCount;
            h.isCompleted = todayCount >= target;
        });
        const activeHabits = habits.sort((a, b) => b.createdAt - a.createdAt);
        const historyItems = items.filter(t => (t.isCompleted || t.isCancelled || t.isDeleted) && (t.type !== 'habit' || t.isDeleted)).sort((a, b) => b.createdAt - a.createdAt);

        const repeatingHistoryItems = [];
        tasks.forEach(t => {
            const hasRepeat = t.frequency && t.frequency !== 'none';
            if (hasRepeat && t.completedDates) {
                t.completedDates.forEach(dateStr => {
                    repeatingHistoryItems.push({
                        ...t,
                        id: t.id + '_completed_' + dateStr, 
                        isCompleted: true,
                        completedAtDate: dateStr, 
                        title: t.title + ` (Completed ${dateStr})`,
                        startDate: dateStr,
                        dueDate: null, 
                        isVirtualOccurrence: true,
                        originalTaskId: t.id
                    });
                });
            }
        });

        const allHabits = items.filter(i => i.type === 'habit');
        allHabits.forEach(h => {
            if (h.completedDates) {
                h.completedDates.forEach(dateStr => {
                    repeatingHistoryItems.push({
                        ...h,
                        id: h.id + '_completed_' + dateStr, 
                        isCompleted: true,
                        completedAtDate: dateStr, 
                        title: h.title + ` (Completed ${dateStr})`,
                        startDate: dateStr,
                        dueDate: null, 
                        isVirtualOccurrence: true,
                        originalTaskId: h.id
                    });
                });
            }
        });

        const combinedHistoryItems = [...historyItems, ...repeatingHistoryItems].sort((a, b) => {
            const dateA = a.completedAtDate || a.startDate || '';
            const dateB = b.completedAtDate || b.startDate || '';
            if (dateA && dateB && dateA !== dateB) {
                return dateB.localeCompare(dateA); // Sort by completion/occurrence date first
            }
            return b.createdAt - a.createdAt;
        });

        if (pomodoroSelect) {
            const pomodoroOptions = document.getElementById('pomodoro-task-options');
            if (pomodoroOptions) {
                let html = '<div class="custom-select-option" data-value="">No specific task</div>';
                window.activeTasksList.forEach(t => {
                    html += `<div class="custom-select-option" data-value="${t.id}">${t.title}</div>`;
                });
                pomodoroOptions.innerHTML = html;
                
                const selectVal = pomodoroSelect.value;
                if (selectVal) {
                    const selectedTask = window.activeTasksList.find(t => String(t.id) === String(selectVal));
                    if (selectedTask) {
                        if (window.customPomodoroTaskSelect) {
                            window.customPomodoroTaskSelect.setValue(selectedTask.id, selectedTask.title);
                        }
                    } else {
                        pomodoroSelect.value = '';
                        if (window.customPomodoroTaskSelect) {
                            window.customPomodoroTaskSelect.setValue('', 'No specific task');
                        }
                    }
                } else {
                    if (window.customPomodoroTaskSelect) {
                        window.customPomodoroTaskSelect.setValue('', 'No specific task');
                    }
                }
            }
            if (pomodoroBtn) pomodoroBtn.style.display = pomodoroSelect.value ? 'block' : 'none';
        }

        if (habitsContainer && activeHabits.length === 0) habitsContainer.innerHTML = '<p class="empty-state">No active habits. Create one!</p>';
        if (historyContainer && combinedHistoryItems.length === 0) historyContainer.innerHTML = '<p class="empty-state">No completed or cancelled items yet.</p>';

        if (habitsContainer) {
            habitsContainer.innerHTML = activeHabits.map(t => renderTaskCard(t, { isHistory: false, showHabitCalendar: true, showSubtasks: true })).join('');
        }
        if (historyContainer) {
            historyContainer.innerHTML = combinedHistoryItems.map(t => renderTaskCard(t, { isHistory: true, showHabitCalendar: false, showSubtasks: false })).join('');
        }

        sortAndRenderDashboard();
        // Note: window.sortAndRenderDashboard is also assigned once at module level
        // below; the assignment here is kept for timing safety on first load.
    });
}

function sortAndRenderDashboard() {
    const container = document.getElementById('dashboard-view-container');
    if (!container) return;

    const now = new Date();
    let fingerprint = `${window.currentTaskFilter || 'all'}:${window.currentCategoryFilter || 'all'}:${window.currentTaskSort || 'default'}:${window.customFilterStartDate || ''}:${window.customFilterEndDate || ''}|`;
    (window.activeTasksList || []).forEach(item => {
        let startInstant = item.startDate ? parseLocalISOString(item.startDate, item.startTime || '00:00') : now;
        let dueInstant = item.dueDate ? parseLocalISOString(item.dueDate, item.dueTime || '23:59') : null;
        let cat = "current";
        if (dueInstant && dueInstant < now) cat = "overdue";
        else if (startInstant > now) cat = "upcoming";
        fingerprint += `${item.id}:${cat}|`;
    });
    window.lastDashboardFingerprint = fingerprint;

    const board = container.querySelector('.kanban-board');
    const savedScrollLeft = board ? board.scrollLeft : 0;
    
    const columns = container.querySelectorAll('.kanban-column');
    const savedScrollTops = Array.from(columns).map(col => col.scrollTop);

    const upcomingTasks = [];
    const currentTasks = [];
    const overdueTasks = [];

    let filteredTasks = [...(window.activeTasksList || [])];

    const filterVal = window.currentTaskFilter || 'all';
    if (filterVal !== 'all') {
        const todayStr = now.toLocaleDateString('sv'); 
        
        const tomorrow = new Date();
        tomorrow.setDate(now.getDate() + 1);
        const tomorrowStr = tomorrow.toLocaleDateString('sv');
        
        const getWeekBounds = (d) => {
            const start = new Date(d);
            const day = start.getDay();
            const diff = start.getDate() - day + (day === 0 ? -6 : 1);
            const monday = new Date(start.setDate(diff));
            monday.setHours(0,0,0,0);
            
            const sunday = new Date(monday);
            sunday.setDate(monday.getDate() + 6);
            sunday.setHours(23,59,59,999);
            return { start: monday, end: sunday };
        };
        const weekBounds = getWeekBounds(now);
        const weekStartStr = weekBounds.start.toLocaleDateString('sv');
        const weekEndStr = weekBounds.end.toLocaleDateString('sv');

        filteredTasks = filteredTasks.filter(item => {
            const rawStart = item.startDate || item.dueDate;
            const rawDue = item.dueDate || item.startDate;
            if (!rawStart && !rawDue) return false;
            
            const taskStart = rawStart <= rawDue ? rawStart : rawDue;
            const taskEnd = rawDue >= rawStart ? rawDue : rawStart;

            if (filterVal === 'today') {
                return taskStart <= todayStr && taskEnd >= todayStr;
            }
            if (filterVal === 'tomorrow') {
                return taskStart <= tomorrowStr && taskEnd >= tomorrowStr;
            }
            if (filterVal === 'week') {
                return taskStart <= weekEndStr && taskEnd >= weekStartStr;
            }
            if (filterVal === 'month') {
                const monthStartStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-01`;
                const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
                const monthEndStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;
                return taskStart <= monthEndStr && taskEnd >= monthStartStr;
            }
            if (filterVal === 'year') {
                const yearStartStr = `${now.getFullYear()}-01-01`;
                const yearEndStr = `${now.getFullYear()}-12-31`;
                return taskStart <= yearEndStr && taskEnd >= yearStartStr;
            }
            if (filterVal === 'custom') {
                if (!window.customFilterStartDate || !window.customFilterEndDate) return true;
                return taskStart <= window.customFilterEndDate && taskEnd >= window.customFilterStartDate;
            }
            return true;
        });
    }

    const categoryVal = window.currentCategoryFilter || 'all';
    if (categoryVal !== 'all') {
        filteredTasks = filteredTasks.filter(item => {
            const itemCat = item.category || 'Work';
            return itemCat.toLowerCase() === categoryVal.toLowerCase();
        });
    }

    const sortVal = window.currentTaskSort || 'default';
    if (sortVal === 'a-z') {
        filteredTasks.sort((a, b) => a.title.localeCompare(b.title));
    } else if (sortVal === 'z-a') {
        filteredTasks.sort((a, b) => b.title.localeCompare(a.title));
    } else if (sortVal === 'priority') {
        const priorityWeight = { high: 3, medium: 2, low: 1 };
        filteredTasks.sort((a, b) => {
            const weightA = priorityWeight[a.priority] || 2;
            const weightB = priorityWeight[b.priority] || 2;
            return weightB - weightA;
        });
    } else if (sortVal === 'time') {
        filteredTasks.sort((a, b) => {
            const timeA = new Date(`${a.startDate}T${a.startTime || '00:00'}`).getTime();
            const timeB = new Date(`${b.startDate}T${b.startTime || '00:00'}`).getTime();
            return timeA - timeB;
        });
    }

    filteredTasks.forEach(item => {
        let startInstant = item.startDate ? parseLocalISOString(item.startDate, item.startTime || '00:00') : now;
        let dueInstant = item.dueDate ? parseLocalISOString(item.dueDate, item.dueTime || '23:59') : null;

        if (dueInstant && dueInstant < now) {
            overdueTasks.push(item);
        } else if (startInstant > now) {
            upcomingTasks.push(item);
        } else {
            currentTasks.push(item);
        }
    });

    const layout = localStorage.getItem('dashboardLayout') || 'list';

    if (layout === 'kanban') {
        let html = '<div class="kanban-board">';

        html += `
            <div class="kanban-column" style="border-top: 3px solid #FF4D4F;">
                <div class="dashboard-view-header">
                    <span class="dashboard-view-title" style="color: #FF4D4F; font-size: 13.5px;"><i class="fa-solid fa-circle-exclamation"></i> Overdue</span>
                    <span class="dashboard-view-count badge-overdue">${overdueTasks.length}</span>
                </div>
                <div class="tasks-container">
                    ${overdueTasks.length === 0 ? '<p class="empty-state" style="padding:16px 0; font-size:12px;">No overdue tasks</p>' : overdueTasks.map(t => renderTaskCard(t, { isHistory: false, showHabitCalendar: false, showSubtasks: false })).join('')}
                </div>
            </div>
        `;

        html += `
            <div class="kanban-column" style="border-top: 3px solid var(--color-ticktick-blue);">
                <div class="dashboard-view-header">
                    <span class="dashboard-view-title" style="color: var(--color-ticktick-blue); font-size: 13.5px;"><i class="fa-solid fa-play"></i> Current</span>
                    <span class="dashboard-view-count badge-current">${currentTasks.length}</span>
                </div>
                <div class="tasks-container">
                    ${currentTasks.length === 0 ? '<p class="empty-state" style="padding:16px 0; font-size:12px;">No current tasks</p>' : currentTasks.map(t => renderTaskCard(t, { isHistory: false, showHabitCalendar: false, showSubtasks: false })).join('')}
                </div>
            </div>
        `;

        html += `
            <div class="kanban-column" style="border-top: 3px solid #73D13D;">
                <div class="dashboard-view-header">
                    <span class="dashboard-view-title" style="color: #73D13D; font-size: 13.5px;"><i class="fa-solid fa-forward"></i> Upcoming</span>
                    <span class="dashboard-view-count badge-upcoming">${upcomingTasks.length}</span>
                </div>
                <div class="tasks-container">
                    ${upcomingTasks.length === 0 ? '<p class="empty-state" style="padding:16px 0; font-size:12px;">No upcoming tasks</p>' : upcomingTasks.map(t => renderTaskCard(t, { isHistory: false, showHabitCalendar: false, showSubtasks: false })).join('')}
                </div>
            </div>
        `;

        html += '</div>';

        if (container.innerHTML !== html) {
            container.innerHTML = html;

            const newBoard = container.querySelector('.kanban-board');
            if (newBoard) {
                newBoard.scrollLeft = savedScrollLeft;
            }
            const newColumns = container.querySelectorAll('.kanban-column');
            newColumns.forEach((col, idx) => {
                if (savedScrollTops[idx] !== undefined) {
                    col.scrollTop = savedScrollTops[idx];
                }
            });
        }
    } else {
        let html = '<div class="standard-board">';

        if (overdueTasks.length > 0) {
            html += `
                <div class="tasks-list-card" style="border-color: #FF4D4F44; background-color: #FF4D4F08;">
                    <div class="dashboard-view-header">
                        <span class="dashboard-view-title" style="color: #FF4D4F;"><i class="fa-solid fa-circle-exclamation"></i> Overdue Tasks</span>
                        <span class="dashboard-view-count badge-overdue">${overdueTasks.length}</span>
                    </div>
                    <div class="tasks-container">
                        ${overdueTasks.map(t => renderTaskCard(t, { isHistory: false, showHabitCalendar: false, showSubtasks: false })).join('')}
                    </div>
                </div>
            `;
        }

        html += `
            <div class="tasks-list-card">
                <div class="dashboard-view-header">
                    <span class="dashboard-view-title" style="color: var(--color-ticktick-blue);"><i class="fa-solid fa-play"></i> Current Tasks</span>
                    <span class="dashboard-view-count badge-current">${currentTasks.length}</span>
                </div>
                <div class="tasks-container">
                    ${currentTasks.length === 0 ? '<p class="empty-state">No current tasks active.</p>' : currentTasks.map(t => renderTaskCard(t, { isHistory: false, showHabitCalendar: false, showSubtasks: false })).join('')}
                </div>
            </div>
        `;

        html += `
            <div class="tasks-list-card">
                <div class="dashboard-view-header">
                    <span class="dashboard-view-title" style="color: #73D13D;"><i class="fa-solid fa-forward"></i> Upcoming Tasks</span>
                    <span class="dashboard-view-count badge-upcoming">${upcomingTasks.length}</span>
                </div>
                <div class="tasks-container">
                    ${upcomingTasks.length === 0 ? '<p class="empty-state">No upcoming tasks scheduled.</p>' : upcomingTasks.map(t => renderTaskCard(t, { isHistory: false, showHabitCalendar: false, showSubtasks: false })).join('')}
                </div>
            </div>
        `;

        html += '</div>';

        if (container.innerHTML !== html) {
            container.innerHTML = html;
        }
    }
}

window.sortAndRenderDashboard = sortAndRenderDashboard;

function cancelItem(id) {
    showConfirm('Mark this task as "Won\'t Do"?', () => {
        getTasksFromFirebase().then(tasks => {
            const item = tasks.find(t => String(t.id) === String(id));
            if (item) {
                item.isCancelled = true;
                item.isCompleted = false; 
                saveTaskToFirebase(item).then(() => {
                    if (scheduleItemNotifications) {
                        scheduleItemNotifications(item);
                    }
                    showToast('Task marked as Won\'t Do', 'info', false);
                    displayTasks();
                    if (window.calendarInstance) window.calendarInstance.refetchEvents();
                });
            }
        });
    });
}

window.cancelItem = cancelItem;

function restoreItem(id) {
    if (String(id).includes('_completed_')) {
        const [originalId, completedDate] = id.split('_completed_');
        getTasksFromFirebase().then(tasks => {
            const item = tasks.find(t => String(t.id) === String(originalId));
            if (item && item.completedDates) {
                item.completedDates = item.completedDates.filter(d => d !== completedDate);
                
                if (completedDate < item.startDate) {
                    const currentStart = new Date(item.startDate);
                    const restoredStart = new Date(completedDate);
                    const diffTime = currentStart - restoredStart;
                    const diffDays = Math.round(diffTime / (1000 * 60 * 60 * 24));
                    
                    item.startDate = completedDate;
                    
                    if (item.dueDate) {
                        const currentDue = new Date(item.dueDate);
                        const restoredDue = new Date(currentDue);
                        restoredDue.setDate(restoredDue.getDate() - diffDays);
                        
                        const dy = restoredDue.getFullYear();
                        const dm = String(restoredDue.getMonth() + 1).padStart(2, '0');
                        const dd = String(restoredDue.getDate()).padStart(2, '0');
                        item.dueDate = `${dy}-${dm}-${dd}`;
                    }
                }

                saveTaskToFirebase(item).then(() => {
                    showToast('Occurrence restored!', 'info', false);
                    displayTasks();
                    if (window.calendarInstance) window.calendarInstance.refetchEvents();
                });
            }
        });
        return;
    }

    getTasksFromFirebase().then(tasks => {
        const item = tasks.find(t => String(t.id) === String(id));
        if (item) {
            item.isCompleted = false;
            item.isCancelled = false;
            item.isDeleted = false;
            item.completedCount = 0;
            saveTaskToFirebase(item).then(() => {
                if (scheduleItemNotifications) {
                    scheduleItemNotifications(item);
                }
                showToast('Task restored!', 'info', false);
                displayTasks();
                if (window.calendarInstance) window.calendarInstance.refetchEvents();
            });
        }
    });
}

window.restoreItem = restoreItem;

function deleteItem(id) {
    if (String(id).includes('_completed_')) {
        const [originalId, completedDate] = id.split('_completed_');
        showConfirm('Permanently delete this occurrence from history?', () => {
            getTasksFromFirebase().then(tasks => {
                const item = tasks.find(t => String(t.id) === String(originalId));
                if (item && item.completedDates) {
                    item.completedDates = item.completedDates.filter(d => d !== completedDate);
                    saveTaskToFirebase(item).then(() => {
                        showToast('Occurrence deleted', 'success', false);
                        displayTasks();
                        if (window.calendarInstance) window.calendarInstance.refetchEvents();
                    });
                }
            });
        });
        return;
    }

    getTasksFromFirebase().then(tasks => {
        const item = tasks.find(t => String(t.id) === String(id));
        if (!item) return;
        
        if (item.isCompleted || item.isCancelled || item.isDeleted) {
            showConfirm('Permanently delete this item from history?', () => {
                deleteTaskFromFirebase(id).then(() => {
                    showToast('Permanently deleted', 'success', false);
                    displayTasks();
                    if (window.calendarInstance) window.calendarInstance.refetchEvents();
                });
            });
        } else {
            const typeLabel = item.type === 'habit' ? 'habit' : (item.type === 'event' ? 'event' : 'task');
            const confirmMsg = `Are you sure you want to delete this ${typeLabel}?`;
            const toastMsg = item.type === 'habit' 
                ? 'Habit deleted' 
                : (item.type === 'event' ? 'Event moved to history' : 'Task moved to history');

            showConfirm(confirmMsg, () => {
                item.isDeleted = true;
                item.isCompleted = false;
                item.isCancelled = false;
                saveTaskToFirebase(item).then(() => {
                    if (scheduleItemNotifications) {
                        scheduleItemNotifications(item);
                    }
                    showToast(toastMsg, 'success', false);
                    displayTasks();
                    if (window.calendarInstance) window.calendarInstance.refetchEvents();
                });
            });
        }
    });
}

window.deleteItem = deleteItem;

function toggleItemComplete(id, currentStatus) {
    getTasksFromFirebase().then(tasks => {
        const item = tasks.find(t => String(t.id) === String(id));
        if (!item) return;

        const todayStr = getTodayStr();

        const hasRepeat = item.frequency && item.frequency !== 'none';

        if (item.type === 'habit') {
            const target = item.timesPerDay || 1;
            if (!item.dailyProgress) item.dailyProgress = {};
            if (!item.completedDates) item.completedDates = [];

            if (currentStatus) {
                // If already completed today, toggle resets progress for today
                item.dailyProgress[todayStr] = 0;
                item.completedDates = item.completedDates.filter(d => d !== todayStr);
                item.isCompleted = false;
                item.completedCount = 0;
            } else {
                let currentCount = item.dailyProgress[todayStr] || 0;
                currentCount += 1;
                item.dailyProgress[todayStr] = currentCount;
                item.completedCount = currentCount;

                if (currentCount >= target) {
                    item.isCompleted = true;
                    if (!item.completedDates.includes(todayStr)) {
                        item.completedDates.push(todayStr);
                    }
                    if (item.skippedDates) {
                        item.skippedDates = item.skippedDates.filter(d => d !== todayStr);
                    }
                    showToast('Awesome! Marked as complete.', 'success', true);
                } else {
                    item.isCompleted = false;
                    playSound('check');
                    showToast(`Good job! ${currentCount}/${target} completed.`, 'info', false);
                }
            }
        } else if (hasRepeat) {
            if (!item.completedDates) item.completedDates = [];
            
            if (!item.completedDates.includes(item.startDate)) {
                item.completedDates.push(item.startDate);
            }

            Promise.resolve().then(() => {
                let nextStart = getNextOccurrenceTime(
                    item.startDate,
                    item.startTime || '09:00',
                    item.frequency,
                    item.specificDays,
                    item.customNum,
                    item.customUnit,
                    false
                );

                if (!nextStart) {
                    nextStart = new Date(item.startDate);
                    nextStart.setDate(nextStart.getDate() + 1);
                }

                const ny = nextStart.getFullYear();
                const nm = String(nextStart.getMonth() + 1).padStart(2, '0');
                const nd = String(nextStart.getDate()).padStart(2, '0');
                const nextStartDateStr = `${ny}-${nm}-${nd}`;

                if (item.dueDate) {
                    const currentStart = new Date(item.startDate);
                    const currentDue = new Date(item.dueDate);
                    const diffTime = currentDue - currentStart;
                    const diffDays = Math.round(diffTime / (1000 * 60 * 60 * 24));

                    const nextDue = new Date(nextStart);
                    nextDue.setDate(nextDue.getDate() + diffDays);
                    
                    const dy = nextDue.getFullYear();
                    const dm = String(nextDue.getMonth() + 1).padStart(2, '0');
                    const dd = String(nextDue.getDate()).padStart(2, '0');
                    item.dueDate = `${dy}-${dm}-${dd}`;
                }

                item.startDate = nextStartDateStr;
                item.isCompleted = false; 
                item.completedCount = 0;
                item.lastCompletedDate = todayStr;
                showToast('Awesome! Marked as complete.', 'success', true);

                saveTaskToFirebase(item).then(() => {
                    if (scheduleItemNotifications) {
                        scheduleItemNotifications(item);
                    }
                    displayTasks();
                    if (window.calendarInstance) window.calendarInstance.refetchEvents();
                    
                    const pomSelect = document.getElementById('pomodoro-task-select');
                    if (pomSelect && pomSelect.value == id && item.isCompleted) {
                        pomSelect.value = '';
                        document.getElementById('pomodoro-mark-done').style.display = 'none';
                    }
                });
            });
            return;
        } else {
            if (!currentStatus) { 
                item.completedCount = (item.completedCount || 0) + 1;
                if (item.completedCount >= (item.timesPerDay || 1)) {
                    item.isCompleted = true;
                    showToast('Awesome! Marked as complete.', 'success', true);
                } else {
                    playSound('check');
                    showToast(`Good job! ${item.completedCount}/${item.timesPerDay} completed.`, 'info', false);
                }
            } else { 
                item.isCompleted = false;
                item.completedCount = 0;
            }
        }

        saveTaskToFirebase(item).then(() => {
            displayTasks();
            if (window.calendarInstance) window.calendarInstance.refetchEvents();
            
            const pomSelect = document.getElementById('pomodoro-task-select');
            if (pomSelect && pomSelect.value == id && item.isCompleted) {
                pomSelect.value = '';
                document.getElementById('pomodoro-mark-done').style.display = 'none';
            }
        });
    });
}

window.toggleItemComplete = toggleItemComplete;

function toggleHabitDay(event, id, dateStr) {
    if (event) event.stopPropagation();
    getTasksFromFirebase().then(tasks => {
        const item = tasks.find(t => String(t.id) === String(id));
        if (!item) return;
        
        if (!item.completedDates) item.completedDates = [];
        if (!item.skippedDates) item.skippedDates = [];
        if (!item.dailyProgress) item.dailyProgress = {};
        const target = item.timesPerDay || 1;
        
        const doneIdx = item.completedDates.indexOf(dateStr);
        const skippedIdx = item.skippedDates.indexOf(dateStr);
        
        if (doneIdx === -1 && skippedIdx === -1) {
            item.completedDates.push(dateStr);
            item.dailyProgress[dateStr] = target;
            playSound('check');
        } else if (doneIdx > -1) {
            item.completedDates.splice(doneIdx, 1);
            item.skippedDates.push(dateStr);
            delete item.dailyProgress[dateStr];
        } else if (skippedIdx > -1) {
            item.skippedDates.splice(skippedIdx, 1);
            delete item.dailyProgress[dateStr];
        }
        
        const todayStr = getTodayStr();
        const todayCount = (item.dailyProgress && item.dailyProgress[todayStr]) || (item.completedDates.includes(todayStr) ? target : 0);
        item.completedCount = todayCount;
        item.isCompleted = todayCount >= target;
        
        saveTaskToFirebase(item).then(() => {
            displayTasks();
            if (window.calendarInstance) window.calendarInstance.refetchEvents();
        });
    });
}

window.toggleHabitDay = toggleHabitDay;

function toggleSubtask(taskId, subIdx, currentStatus) {
    getTasksFromFirebase().then(tasks => {
        const item = tasks.find(t => String(t.id) === String(taskId));
        if (item && item.subtasks) {
            item.subtasks[subIdx].completed = !currentStatus;
            if (!currentStatus) playSound('check');
            saveTaskToFirebase(item).then(() => displayTasks());
        }
    });
}

window.toggleSubtask = toggleSubtask;

// NOTE: getColor is defined in utils.js (returns #FF4D4F high, #2F7BF6 low, #FFA940 medium).
// The duplicate that was here has been removed. All callers in this file use the
// global function from utils.js which is bundled first.

function showItemDetails(id) {
    if (window._justSwipedTaskId) return;
    getTasksFromFirebase().then(tasks => {
        const item = tasks.find(t => String(t.id) === String(id));
        if (!item) return;

        const modal = document.getElementById('details-modal');
        if (!modal) return;

        const titleEl = document.getElementById('details-modal-title');
        const bodyEl = document.getElementById('details-modal-body');
        const actionsEl = document.getElementById('details-modal-actions');

        let typeLabel = item.type || 'task';
        let priorityLabel = item.priority || 'medium';
        let priorityFlag = '';
        if (priorityLabel === 'high') priorityFlag = '<i class="fa-solid fa-flag" style="color: #FF4D4F;"></i> High';
        else if (priorityLabel === 'low') priorityFlag = '<i class="fa-solid fa-flag" style="color: #2F7BF6;"></i> Low';
        else priorityFlag = '<i class="fa-solid fa-flag" style="color: #FFA940;"></i> Medium';

        titleEl.textContent = item.title;

        let scheduleHTML = '';
        if (item.type === 'event') {
            const startVal = item.startDate + (item.startTime ? ` at ${formatTime12h(item.startTime)}` : '');
            const endVal = item.endDate + (item.endTime ? ` at ${formatTime12h(item.endTime)}` : '');
            scheduleHTML = `
                <div class="details-block">
                    <span class="details-block-label">Duration</span>
                    <span class="details-block-value"><i class="fa-regular fa-calendar"></i> ${startVal} <br>to<br> <i class="fa-regular fa-calendar"></i> ${endVal}</span>
                </div>
            `;
        } else {
            const startVal = item.startDate + (item.startTime ? ` at ${formatTime12h(item.startTime)}` : '');
            const dueVal = item.dueDate ? `${item.dueDate}` : 'No deadline';
            scheduleHTML = `
                <div class="form-row" style="gap: 16px; margin-bottom: 0;">
                    <div class="details-block" style="flex: 1;">
                        <span class="details-block-label">Start Date</span>
                        <span class="details-block-value"><i class="fa-regular fa-calendar"></i> ${startVal}</span>
                    </div>
                    ${item.type === 'task' ? `
                    <div class="details-block" style="flex: 1;">
                        <span class="details-block-label">Deadline</span>
                        <span class="details-block-value"><i class="fa-regular fa-calendar-xmark"></i> ${dueVal}</span>
                    </div>
                    ` : ''}
                </div>
            `;
            if (item.type === 'habit') {
                if (item.timesPerDay && item.timesPerDay > 1) {
                    scheduleHTML += `
                        <div class="details-block" style="margin-top: 12px;">
                            <span class="details-block-label">Daily Goal</span>
                            <span class="details-block-value"><i class="fa-solid fa-repeat"></i> ${item.timesPerDay} times per day</span>
                        </div>
                    `;
                }
                if (item.reminderTimes && item.reminderTimes.length > 0) {
                    const timesStr = item.reminderTimes.map(t => formatTime12h(t)).join(', ');
                    scheduleHTML += `
                        <div class="details-block" style="margin-top: 12px;">
                            <span class="details-block-label">Reminder Timers</span>
                            <span class="details-block-value"><i class="fa-regular fa-bell"></i> ${timesStr}</span>
                        </div>
                    `;
                }
            }
        }

        let descHTML = '';
        if (item.description) {
            descHTML = `
                <div class="details-block">
                    <span class="details-block-label">Description / Notes</span>
                    <div class="details-description-box">${item.description}</div>
                </div>
            `;
        }

        let repeatHTML = '';
        if (item.frequency && item.frequency !== 'none') {
            let freqLabel = '';
            if (item.frequency === 'custom') freqLabel = `Every ${item.customNum} ${item.customUnit}`;
            else if (item.frequency === 'specific_days') freqLabel = 'Specific Days';
            else freqLabel = item.frequency.charAt(0).toUpperCase() + item.frequency.slice(1);

            let daysText = '';
            if ((item.frequency === 'specific_days' || item.frequency === 'weekly') && item.specificDays && item.specificDays.length > 0) {
                const dayNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
                daysText = `<div style="font-size: 13px; color: var(--text-muted); margin-top: 4px;">Days: ${item.specificDays.map(d => dayNames[d]).join(', ')}</div>`;
            }

            repeatHTML = `
                <div class="details-block">
                    <span class="details-block-label">Repetition</span>
                    <span class="details-block-value"><i class="fa-solid fa-repeat"></i> ${freqLabel} ${item.timesPerDay > 1 ? `(${item.timesPerDay} times per day)` : ''}</span>
                    ${daysText}
                </div>
            `;
        }

        let subtasksHTML = '';
        if (item.subtasks && item.subtasks.length > 0) {
            subtasksHTML = `
                <div class="details-block">
                    <span class="details-block-label">Sub-tasks checklist</span>
                    <ul class="details-subtasks-list">
            `;
            item.subtasks.forEach((sub, idx) => {
                subtasksHTML += `
                    <li class="details-subtask-item ${sub.completed ? 'completed' : ''}">
                        <input type="checkbox" class="custom-checkbox" ${sub.completed ? 'checked' : ''} onchange="toggleSubtaskInDetails('${item.id}', ${idx}, ${sub.completed})">
                        <span class="details-subtask-text">${sub.title}</span>
                    </li>
                `;
            });
            subtasksHTML += `
                    </ul>
                </div>
            `;
        }

        let categoryBadgeDetails = '';
        if (item.type === 'task' || !item.type) {
            const cat = item.category || 'Work';
            const catMeta = getCategoryMeta(cat);
            categoryBadgeDetails = `<span class="task-category-pill" style="border: 1px solid ${catMeta.color}35; background:${catMeta.bg}; color:${catMeta.color}; padding: 4px 10px; border-radius: 12px; font-size:12px; font-weight:600;"><i class="fa-solid ${catMeta.icon}"></i> ${catMeta.name}</span>`;
        }

        bodyEl.innerHTML = `
            <div class="details-meta-row">
                <span class="details-badge ${typeLabel}">${typeLabel}</span>
                ${item.type === 'task' ? `<span class="details-priority">${priorityFlag}</span>` : ''}
                ${categoryBadgeDetails}
                ${item.isCompleted ? `<span class="badge-completed" style="background: rgba(115,209,61,0.15); color: #73D13D; padding: 4px 10px; border-radius: 12px; font-size:12px; font-weight:600;">Completed</span>` : ''}
                ${item.isCancelled ? `<span class="badge-cancelled" style="background: rgba(255,77,79,0.15); color: #FF4D4F; padding: 4px 10px; border-radius: 12px; font-size:12px; font-weight:600;">Cancelled</span>` : ''}
            </div>
            ${scheduleHTML}
            ${repeatHTML}
            ${descHTML}
            ${subtasksHTML}
        `;

        let cancelBtn = (!item.isCompleted && !item.isCancelled && item.type !== 'habit');

        let desktopHTML = `
            <button class="btn btn-secondary" title="Delete" style="color: #FF4D4F; border-color: #FF4D4F33; background: #FF4D4F11;" onclick="deleteItemInDetails('${item.id}')"><i class="fa-solid fa-trash"></i></button>
            ${cancelBtn ? `<button class="btn btn-secondary" title="Won't Do" onclick="cancelItemInDetails('${item.id}')"><i class="fa-solid fa-ban"></i></button>` : ''}
            <button class="btn btn-primary" title="Edit" onclick="editItem('${item.id}')"><i class="fa-solid fa-pen"></i></button>
        `;

        if (!item.isCompleted && !item.isCancelled) {
            if (item.type === 'habit') {
                let count = item.completedCount || 0;
                desktopHTML += `<button class="btn btn-secondary" title="Won't Do Today" onclick="skipHabitInDetails('${item.id}')"><i class="fa-solid fa-ban"></i></button>`;
                desktopHTML += `<button class="btn btn-primary" title="Log Progress (${count}/${item.timesPerDay})" onclick="logHabitInDetails('${item.id}')"><i class="fa-solid fa-check"></i></button>`;
            } else {
                desktopHTML += `<button class="btn btn-primary" style="background-color:#73D13D; border-color:#73D13D;" title="Complete" onclick="completeItemInDetails('${item.id}')"><i class="fa-solid fa-check"></i></button>`;
            }
        } else {
            desktopHTML += `<button class="btn btn-secondary" title="Restore" onclick="restoreItemInDetails('${item.id}')"><i class="fa-solid fa-rotate-left"></i></button>`;
        }

        let mobileHTML = `
            <button class="details-kebab-option" onclick="editItem('${item.id}')"><i class="fa-solid fa-pen"></i> Edit</button>
        `;
        if (cancelBtn) {
            mobileHTML += `<button class="details-kebab-option" onclick="cancelItemInDetails('${item.id}')"><i class="fa-solid fa-ban"></i> Won't Do</button>`;
        }
        if (!item.isCompleted && !item.isCancelled) {
            if (item.type === 'habit') {
                let count = item.completedCount || 0;
                mobileHTML += `<button class="details-kebab-option" onclick="skipHabitInDetails('${item.id}')"><i class="fa-solid fa-ban"></i> Won't Do Today</button>`;
                mobileHTML += `<button class="details-kebab-option" onclick="logHabitInDetails('${item.id}')"><i class="fa-solid fa-check"></i> Log Progress (${count}/${item.timesPerDay})</button>`;
            } else {
                mobileHTML += `<button class="details-kebab-option" onclick="completeItemInDetails('${item.id}')"><i class="fa-solid fa-check"></i> Complete</button>`;
            }
        } else {
            mobileHTML += `<button class="details-kebab-option" onclick="restoreItemInDetails('${item.id}')"><i class="fa-solid fa-rotate-left"></i> Restore</button>`;
        }
        mobileHTML += `
            <button class="details-kebab-option delete" onclick="deleteItemInDetails('${item.id}')"><i class="fa-solid fa-trash"></i> Delete</button>
        `;

        const desktopContainer = document.getElementById('details-actions-desktop');
        const mobileDropdown = document.getElementById('details-kebab-menu');
        const kebabBtn = document.getElementById('details-kebab-btn');

        if (desktopContainer) desktopContainer.innerHTML = desktopHTML;
        if (mobileDropdown) mobileDropdown.innerHTML = mobileHTML;

        if (mobileDropdown) mobileDropdown.classList.remove('show');

        if (kebabBtn && mobileDropdown) {
            kebabBtn.onclick = (e) => {
                e.stopPropagation();
                mobileDropdown.classList.toggle('show');
            };
        }

        // Kebab close handler — remove any previous listener and register a fresh one
        // so we don't accumulate stale listeners on `document` across multiple opens.
        if (_detailsKebabCloseHandler) {
            document.removeEventListener('click', _detailsKebabCloseHandler);
        }
        _detailsKebabCloseHandler = () => {
            if (mobileDropdown) mobileDropdown.classList.remove('show');
        };
        document.addEventListener('click', _detailsKebabCloseHandler);

        const closeDetailsBtn = document.getElementById('close-details-modal');
        if (closeDetailsBtn) {
            closeDetailsBtn.onclick = () => {
                modal.classList.remove('active');
                document.removeEventListener('click', _detailsKebabCloseHandler);
                _detailsKebabCloseHandler = null;
            };
        }

        modal.onclick = (e) => {
            if (e.target === modal) {
                modal.classList.remove('active');
                document.removeEventListener('click', _detailsKebabCloseHandler);
                _detailsKebabCloseHandler = null;
            }
        };

        modal.classList.add('active');
    });
}

